Object.assign(window.__SYN,{"pe:寸+弦": {"o": "寸·弦脉总属肝气为病，以气机郁滞为核心，兼涉火、痰、湿、虚、热诸端。弦为肝脉，寸口见弦，首主肝郁气结，情志不遂、气机不畅；郁久则化火，故主气郁化火，火性上炎而见寸口弦劲；肝木亢盛则乘脾侮肺，故主木乘土金；气郁津凝则痰饮湿阻，故主痰饮湿阻；若弦而兼细数虚弱，则主虚火浮越，阴亏火旺；若弦兼洪滑数急，则主邪热内郁，热壅气滞。诸类之间，以气郁为枢：气郁可化火、生痰、致虚，火盛又可灼津成痰，虚火亦可上浮。故寸弦一脉，实热郁火与虚火浮越为两大纲，而痰湿、木乘、邪热皆由气机失常所派生，临证须结合兼脉症候，辨其虚实寒热。", "c": [{"name": "主肝郁气结", "desc": "弦为肝脉，寸口见弦多主肝气郁结、气机不畅。原文如肝脉弦出寸口，主思虑气结、志意隐曲不伸；左寸关带弦主肝胃气郁；两寸关弦主肝气上逆。皆因情志不遂，肝失疏泄，气郁于中上焦。"}, {"name": "主气郁化火", "desc": "气郁日久则化火，弦脉见于寸口可示郁火内炽。原文谓气有余便是火，左寸独弦主火郁上焦；肝脉弦出寸口为相火内郁、肝火不泄，逆而上行；左右寸口弦劲为火乘金。皆气郁生火、火性上炎之征。"}, {"name": "主痰饮湿阻", "desc": "弦脉主饮，寸关见弦常示痰饮湿浊阻滞气机。原文如右关脉弦为湿气内阻；寸脉沉弦主上焦阻绝、中脘凝塞，为伏饮之诊；右寸关弦滑主痰湿内阻。皆因水湿痰饮停聚，气机被遏，脉道拘急而弦。"}, {"name": "主木乘土金", "desc": "弦为肝木之脉，寸关见弦可示肝木偏旺，乘侮脾土或上侮肺金。原文如右寸关弦为木入金乡、肝木犯肺；两关弦急为木侮土；肝脉弦出寸口示肝气郁而乘脾。皆脏腑相克、气机逆乱之象。"}, {"name": "主虚火浮越", "desc": "寸口弦而兼细数虚弱，可主阴虚火浮、虚不制火。原文如左寸独弦示金水两虚、虚不制火；左尺虚数水不足，寸口弦劲为火乘金；脉弦出寸口而按之细弱，示心肝脾虚、血液已亏。皆阴血亏虚，虚火上浮之候。"}, {"name": "主邪热内郁", "desc": "弦脉亦主邪热郁结、津伤风动。原文如两寸关脉如弦，舌短硬苔干黑、口臭唇破，为邪热耗顿肠胃津液，弦主邪热内郁、津伤风动；暑月痢疾左脉弦，为气郁食积化热。皆邪热壅遏、气机郁滞所致。"}], "n": {"主肝郁气结": 4, "主气郁化火": 3, "主痰饮湿阻": 6, "主木乘土金": 4, "主虚火浮越": 2, "主邪热内郁": 1}, "a": {"3656": "主木乘土金", "4021": "主气郁化火", "4022": "主气郁化火", "6079": "主痰饮湿阻", "6373": "主痰饮湿阻", "7865": "主气郁化火", "7866": "主肝郁气结", "8947": "主痰饮湿阻", "11744": "主痰饮湿阻", "11752": "主木乘土金", "11811": "主虚火浮越", "12613": "主肝郁气结", "12883": "主肝郁气结", "15493": "主木乘土金", "17054": "主肝郁气结", "17891": "主邪热内郁", "21801": "主木乘土金", "21803": "主痰饮湿阻", "21807": "主虚火浮越", "24775": "主痰饮湿阻"}, "t": 20, "np": 0}, "c:大+虚+洪": {"o": "洪大虚脉总起来主虚证与热证两类病机，以虚证为主。其核心特征是脉形洪大而按之虚软无力，甚至重按全无，此乃阴血亏虚、元气不足，阳无所附而浮越于外之象，故主血虚发热、元气亏损、阴亏阳浮等虚证，证似实热而实非热，误服白虎汤必死。若脉洪大而重按有力，或兼滑数，则为实热内盛，如暑热内盛、热盛伤阴之候，治当清热保阴。各类之间，虚证与实证以脉之重按有力无力为辨，虚证宜温补滋阴，实证宜清热泻火，临证须细察脉之根底，不可见洪大即投寒凉。", "c": [{"name": "主血虚发热", "desc": "脉洪大而虚，重按全无，为血虚阳浮之象。原文如“肌热燥热、困渴引饮、目赤面红，其脉洪大而虚，重按全无”，“脉洪大而虚，重按全无，此病多得于饥饱劳役”，“血虚发热……脉洪大而虚，重按全无力”，皆因阴血亏虚，阳无所附而外浮，证似白虎而脉不长实，"}, {"name": "主元气亏损", "desc": "脉洪大而虚，为元气亏损、虚阳外浮之象。原文“儒生左腿近环跳患瘤……脉洪大而虚，气瘤也”，因元气亏损，脓已内溃，故用十全大补汤温补而愈。此脉虽洪大，按之虚软，非实热，乃正气不足、虚阳外越之候。"}, {"name": "主阴亏阳浮", "desc": "脉虚洪豁大，为阴亏于下、阳浮于上之象。原文“顾仙槎年越古稀……按脉虚洪豁大，而舌色干绛，溲赤点滴。证属阴亏”，因阴液枯涸，不能摄纳，故见气喘、躁汗、便难等症，忌投刚燥，当滋阴潜阳。"}, {"name": "主暑热内盛", "desc": "脉洪大滑数，重按有力，为暑热内盛、气血沸涌之象。原文“赵子升夏病疟……脉数重按有力、洪大滑数，为暑热内盛之象”，予白虎汤清解暑热；“暑热时……陡然下痢，多带鲜血，其脉洪大者”，宜大剂白虎汤，若洪大而按之虚，则热盛气阴已伤，宜白虎加人参汤。"}, {"name": "主热盛伤阴", "desc": "脉洪大，按腹如烙，为热蒸气分、阴虚阳亢之象。原文“陈叟久患痰嗽气逆……孟英察脉洪大，按腹如烙”，因误服温补，致痰中带血、气喘而厥、二便不通，皆热壅肺胃、阴液受灼，洪大为阴虚，主热盛伤阴。"}], "n": {"主血虚发热": 4, "主元气亏损": 1, "主阴亏阳浮": 2, "主暑热内盛": 2, "主热盛伤阴": 1}, "a": {"4112": "主元气亏损", "13245": "主阴亏阳浮", "13850": "主阴亏阳浮", "13954": "主暑热内盛", "14066": "主热盛伤阴", "19335": "主血虚发热", "20224": "主暑热内盛", "23974": "主血虚发热", "24290": "主血虚发热", "27137": "主血虚发热"}, "t": 10, "np": 0}, "c:沉+迟": {"o": "沉迟脉总属里、虚、寒之象。沉主病在里，迟主寒，合而主阳气不足、阴寒内盛。其所主病机以里寒阳虚为核心，可兼寒凝气滞、寒痰水饮、虚寒不足、寒积内结，以及津伤筋急之痉病。各段原文多从‘沉主里、迟主寒’立论，或见于伤寒少阴、霍乱、水肿、癃闭、胸痹、腹痛、虚劳等证。类与类之间，总以阳虚寒盛为本，气滞、痰饮、积结为标，虚寒与寒积可相兼，津伤痉病则为变例。故沉迟脉虽主寒，须合兼脉兼症，辨其虚、实、痰、积、津伤之不同。", "c": [{"name": "主里寒阳虚", "desc": "沉主里、迟主寒，合为里阳不足、阴寒内盛之象。原文多言‘沉主里，迟主寒’，见四肢冷、下利完谷、小便不禁、水肿、奔豚、疝瘕等，皆阳气不能温煦固摄所致，故脉沉迟。"}, {"name": "主寒凝气滞", "desc": "迟脉主寒，寒性收引凝滞，气血运行不畅。原文见腹痛、疝冲瘕聚收引拘束痛甚、腰脊板硬、胸痹短气、疟母等，皆寒凝脉络、气机痹阻之征，故脉沉迟。"}, {"name": "主寒痰水饮", "desc": "沉主里、迟主寒，寒痰水饮内伏，阳气不运。原文见寒痰昏睡、痰饮呕吐、胸痹喘息咳唾、水肿腹满、癃闭等，皆寒饮痰浊停聚、气化不利，故脉沉迟。"}, {"name": "主虚寒不足", "desc": "沉迟而无力，为阳气虚衰、气血不足。原文见虚劳虚寒、汗后身痛、亡血脉沉迟、脾肾虚寒腰腿痛、霍乱吐泻等，皆正虚寒伏、营卫不调，故脉沉迟无力。"}, {"name": "主寒积内结", "desc": "沉迟兼紧弦涩，为寒冷积于内、气血凝滞。原文见寒积腹痛、伏寒未泄之霍乱、脏寒腹胀、肠痹真阳内竭等，皆阴寒积结、阳气不能鼓动，故脉沉迟或沉伏。"}, {"name": "主津伤痉病", "desc": "沉迟非尽属寒，亦主津液不足、筋脉失养。原文见太阳痉病身体强、脉反沉迟，用栝蒌桂枝汤解表生津；汗后身痛脉沉迟，为营气不足、筋脉失养，故脉沉迟。"}, {"name": "脉症相反预后", "desc": "指脉象与症状相反时的预后判断。表病当浮大反见沉迟，里病当沉细反见浮大，脉反其候示阴阳错乱，轻则向愈，重则危殆，强调脉症合参以断吉凶。"}, {"name": "脉象阴阳分类", "desc": "指以浮沉大小等脉象特征辨别阴阳虚实。浮、大、数、动、长、滑属阳，沉、涩、弦、弱、短、微属阴，阳病见阴脉逆主死，阴病见阳脉顺主生，为脉学总纲。"}], "n": {"主里寒阳虚": 39, "主寒凝气滞": 18, "主寒痰水饮": 23, "主虚寒不足": 20, "主寒积内结": 5, "主津伤痉病": 5, "脉症相反预后": 1, "脉象阴阳分类": 1}, "a": {"59": "主里寒阳虚", "1251": "主里寒阳虚", "1916": "主里寒阳虚", "3309": "主里寒阳虚", "3522": "主寒积内结", "3798": "主里寒阳虚", "4843": "主里寒阳虚", "4894": "主里寒阳虚", "5040": "主寒痰水饮", "7038": "主里寒阳虚", "7876": "主寒凝气滞", "8391": "主里寒阳虚", "8407": "主寒凝气滞", "8570": "主里寒阳虚", "8579": "主里寒阳虚", "8583": "主寒痰水饮", "8661": "主寒凝气滞", "10100": "主寒痰水饮", "11018": "主里寒阳虚", "12077": "主里寒阳虚", "12122": "主里寒阳虚", "12258": "主寒凝气滞", "12262": "主虚寒不足", "12289": "主寒凝气滞", "12290": "主寒凝气滞", "15037": "主寒痰水饮", "15459": "主寒凝气滞", "15805": "主虚寒不足", "15807": "主寒凝气滞", "15932": "主寒凝气滞", "15981": "主寒积内结", "16137": "主寒凝气滞", "16237": "主寒痰水饮", "16652": "主里寒阳虚", "17247": "主寒凝气滞", "17338": "主里寒阳虚", "18244": "主里寒阳虚", "18281": "主里寒阳虚", "18549": "主虚寒不足", "18664": "主寒痰水饮", "19076": "主寒痰水饮", "19146": "主寒积内结", "19529": "主寒痰水饮", "19563": "主虚寒不足", "19640": "主里寒阳虚", "19655": "主里寒阳虚", "19656": "主里寒阳虚", "19658": "主里寒阳虚", "20916": "主里寒阳虚", "20922": "主里寒阳虚", "20978": "主虚寒不足", "21075": "__np", "21098": "脉症相反预后", "21404": "主里寒阳虚", "21569": "主里寒阳虚", "21739": "主寒凝气滞", "21811": "脉象阴阳分类", "21899": "主里寒阳虚", "21929": "主里寒阳虚", "22006": "主里寒阳虚", "22068": "主寒痰水饮", "22161": "主寒痰水饮", "23106": "主津伤痉病", "23307": "主虚寒不足", "23341": "主寒痰水饮", "24441": "主虚寒不足", "24585": "主津伤痉病", "24602": "主虚寒不足", "24603": "主寒痰水饮", "24621": "主里寒阳虚", "24631": "主寒凝气滞", "24728": "主虚寒不足", "24730": "主虚寒不足", "24731": "主虚寒不足", "24732": "主虚寒不足", "24733": "主虚寒不足", "24785": "主寒痰水饮", "24845": "主里寒阳虚", "24846": "主寒痰水饮", "24847": "主寒痰水饮", "24876": "主寒凝气滞", "24894": "主里寒阳虚", "24906": "主里寒阳虚", "24927": "主寒痰水饮", "24969": "主里寒阳虚", "24972": "主里寒阳虚", "24974": "主寒痰水饮", "25007": "主寒凝气滞", "25017": "主里寒阳虚", "25042": "主里寒阳虚", "25068": "主寒积内结", "25069": "主寒积内结", "25102": "主里寒阳虚", "25239": "主津伤痉病", "25240": "主津伤痉病", "25308": "主寒痰水饮", "25309": "主寒痰水饮", "25358": "主寒痰水饮", "25370": "主寒痰水饮", "25421": "主里寒阳虚", "25728": "主虚寒不足", "25792": "主寒凝气滞", "25814": "主津伤痉病", "25874": "主寒凝气滞", "26042": "主虚寒不足", "26160": "主寒凝气滞", "26710": "主虚寒不足", "26863": "主虚寒不足", "26864": "主虚寒不足", "27098": "主虚寒不足", "27183": "主虚寒不足", "27231": "主寒痰水饮", "27285": "主寒痰水饮"}, "t": 113, "np": 1}, "pc:左+弦+大": {"o": "左·弦大脉总以弦为肝郁气滞、大为邪实或阳亢为纲，所主病机可归纳为肝郁气滞、肝火亢盛、肝阳化风、痰火壅盛、热毒炽盛、邪留血分、阴虚阳亢及虚中夹实八类。弦脉主肝、主痛、主气郁，大脉主邪盛、主火亢、主虚阳外浮，左脉候肝，故弦大并见多反映肝胆气机失调、火盛阳亢，或邪实壅盛。其中肝郁气滞为基本病机，气郁日久可化火成肝火亢盛，火盛动风则为肝阳化风；火炼津液成痰则痰火壅盛，热毒炽盛则气血两燔；邪留血分则血络瘀滞；若素体阴亏，水不涵木，则见阴虚阳亢；若正虚邪恋，则成虚中夹实。诸类之间常相互转化、兼夹，总不离肝木气火失调、邪实与正虚交争之机。", "c": [{"name": "主肝郁气滞", "desc": "弦为气机郁滞，大为邪实气壅。左脉候肝，弦大并见多示肝气郁结、疏泄失常。原文如“左脉弦大，面赤痰多，大便不爽，此劳怒动肝”（1552）、“痞结肝脾气滞，左腹结痞，大便带红，左脉弦大”（6730），皆以弦大主肝郁气滞、木失条达。"}, {"name": "主肝火亢盛", "desc": "弦主肝旺，大主火盛。左脉弦大常为肝火亢逆、气火有余之象。原文如“七情郁结，燥火内燃，咳逆咽干，左脉弦大”（4750）、“心烦头晕，寤不成寐，五火内炽也，诊左脉弦大”（6985），均以弦大示肝火内炽、上扰清窍。"}, {"name": "主肝阳化风", "desc": "弦为肝病，大示阳亢，左脉弦大可见肝阳偏亢、化风上扰。原文如“左脉弦大，面赤痰多……此劳怒动肝，令阳气不交于阴……内风烁筋”（1552）、“左脉弦大，尺部空虚，下虚上实，眩晕不定”（7698），皆以弦大主肝阳上亢、内风动越。"}, {"name": "主痰火壅盛", "desc": "弦主肝郁，大主邪盛，若兼滑象则痰火交结。原文如“左脉弦大，右脉滑大而数……痰火壅盛”（5980）、“左手弦大，右手滑大有力，关部尤甚，此肝家有郁火，胃中有痰”（11425），均以弦大示肝火与痰浊壅盛于内。"}, {"name": "主热毒炽盛", "desc": "弦大为肝胆热盛，若兼洪大、数则热毒弥漫。原文如“春温头痛发热，左脉弦大，右洪大……发斑色紫，神昏……热毒内陷，气血两燔”（6159）、“左关脉弦大鼓指……脉转数，恐作囊痈，急为解毒”（6116），皆以弦大示热毒壅盛、气血两燔。"}, {"name": "主邪留血分", "desc": "左主血，弦大示邪实血瘀。原文如“疟频发，谓之疟，邪留血分也，左脉弦大，右脉细软，和血以托邪则愈”（11284）、“蓄血妄行……左脉弦大，乃血去络不和也”（2242），均以左脉弦大主血分伏邪、络脉瘀滞。"}, {"name": "主阴虚阳亢", "desc": "弦大为肝阳偏亢，若兼尺虚、细软则阴亏于下。原文如“左脉弦大，尺部空虚，下虚上实”（7698）、“左脉弦大，右部大而濡软……肾水肺津、肝阴胃液一齐耗损”（7574），皆以弦大示阴不涵木、虚阳上浮。"}, {"name": "主虚中夹实", "desc": "弦大主邪盛，若重按少力或兼细软，则正虚邪恋。原文如“左脉弦大，右脉濡滑，俱重按少力……久热之下，肝胃阴伤，湿邪未化”（7348）、“左脉弦大，右脉细软……疟频发，邪留血分”（11284），均以弦大示虚实夹杂、正不胜邪。"}], "n": {"主肝郁气滞": 13, "主肝火亢盛": 30, "主肝阳化风": 7, "主痰火壅盛": 11, "主热毒炽盛": 6, "主邪留血分": 1, "主阴虚阳亢": 10, "主虚中夹实": 3}, "a": {"1056": "主肝火亢盛", "1457": "主肝火亢盛", "1552": "主肝阳化风", "2140": "主肝火亢盛", "2242": "主肝郁气滞", "2543": "主肝阳化风", "3291": "主肝郁气滞", "3490": "主肝火亢盛", "3622": "主肝火亢盛", "3755": "主肝火亢盛", "4231": "主肝火亢盛", "4232": "主虚中夹实", "4486": "主肝阳化风", "4574": "主肝火亢盛", "4750": "主肝火亢盛", "4828": "主肝火亢盛", "5195": "主肝郁气滞", "5272": "主肝郁气滞", "5980": "主痰火壅盛", "6097": "主肝火亢盛", "6116": "主热毒炽盛", "6126": "主热毒炽盛", "6145": "主肝郁气滞", "6157": "主痰火壅盛", "6159": "主热毒炽盛", "6207": "主肝火亢盛", "6229": "主肝郁气滞", "6235": "主肝火亢盛", "6257": "主肝郁气滞", "6274": "主痰火壅盛", "6278": "主阴虚阳亢", "6391": "主肝火亢盛", "6411": "主肝郁气滞", "6421": "主热毒炽盛", "6440": "主肝郁气滞", "6452": "主肝阳化风", "6454": "主热毒炽盛", "6460": "主痰火壅盛", "6502": "主肝火亢盛", "6523": "主肝郁气滞", "6528": "主痰火壅盛", "6550": "主痰火壅盛", "6730": "主肝郁气滞", "6842": "主阴虚阳亢", "6894": "主肝阳化风", "6956": "主阴虚阳亢", "6985": "主肝火亢盛", "7171": "主虚中夹实", "7348": "主阴虚阳亢", "7349": "主阴虚阳亢", "7403": "主肝郁气滞", "7528": "主阴虚阳亢", "7574": "主阴虚阳亢", "7648": "主肝阳化风", "7698": "主阴虚阳亢", "7718": "主肝火亢盛", "7750": "主肝郁气滞", "8500": "主阴虚阳亢", "9058": "主虚中夹实", "11226": "主痰火壅盛", "11284": "主邪留血分", "11291": "主阴虚阳亢", "11349": "主肝阳化风", "11421": "主痰火壅盛", "11425": "主痰火壅盛", "11484": "主肝火亢盛", "11501": "主肝火亢盛", "11514": "主痰火壅盛", "11518": "主痰火壅盛", "11748": "主热毒炽盛", "12334": "主肝火亢盛", "12335": "主肝火亢盛", "13568": "主肝火亢盛", "13698": "主肝火亢盛", "14658": "主肝火亢盛", "14823": "主肝火亢盛", "17645": "主肝火亢盛", "17694": "主肝火亢盛", "24832": "主肝火亢盛", "24975": "主肝火亢盛", "24998": "主肝火亢盛"}, "t": 81, "np": 0}, "pc:右+滑+大": {"o": "右滑大脉总以痰、热、实邪壅盛为核心病机。滑主痰湿、痰热、食积，大主邪气有余，右部候肺、脾、胃，故其病位多在中上焦。具体而言，滑大有力多主痰热壅盛或邪实内结；右关滑大常主食积、痰饮、胃热；右寸滑大主痰热壅肺；兼数则热盛，兼弦急则风热郁遏。若与虚象并见，如左细弱、余部无神，则属气虚痰盛或正虚邪实。各证候之间常相互兼夹，如痰热可兼食积，痰湿可兼气虚，临证当脉症合参，辨其主次。", "c": [{"name": "主痰湿内蕴", "desc": "滑脉主痰，大脉主邪盛，右脉候肺、脾、胃，故右滑大常示痰湿壅盛于中上焦。原文多伴咳喘、呕恶、眩晕、胸闷、舌苔腻等，如“右脉滑大，内有痰涎”“滑主痰湿内蕴”。"}, {"name": "主痰热壅盛", "desc": "滑大而数或有力，为痰热交炽之象。原文见“滑主痰热，大示邪盛”，症见咳痰黄稠、壮热烦渴、神昏谵语、舌绛苔黄等，多见于湿温、风温、喘嗽等病。"}, {"name": "主邪实壅盛", "desc": "大脉主邪气有余，滑大有力示实邪壅滞，如食积、痰饮、湿热、风热等。原文谓“大主邪气有余”“滑大有力为邪实”，常伴腹胀、便秘、呕吐、发热等实象。"}, {"name": "主食积内停", "desc": "右关滑大或沉实，主胃中食滞。原文“右关滑大，胃中食滞”“滑大沉实，胃中食滞”，症见脘腹胀闷、嗳腐吞酸、大便不通，治宜消食导滞。"}, {"name": "主风热郁遏", "desc": "右脉滑大兼左弦急，为风热郁遏三阳。原文“右滑大，左弦急，此系风热郁遏三阳”，症见头疼壮热、咳逆烦渴，治当凉解。"}, {"name": "主气虚痰盛", "desc": "右脉滑大而体素弱，或左细弱，为气虚不能运化，痰湿内生。原文“右滑大，左细弱，为体素弱而痰热壅肺”“气虚生痰”，症见喘嗽、肢倦、纳差，治宜补气化痰。"}, {"name": "主胃热上冲", "desc": "右关滑大有力，主胃中湿热蒸燔，迫血上涌或热壅阳明。原文“右关脉滑大有力，主胃中湿热蒸燔”“热壅阳明”，症见吐血、头痛、烦渴，治宜清降胃火。"}, {"name": "相火亢盛", "desc": "右尺滑大主命门相火亢盛，症见燥渴等，属实证可暂泻，但痨瘵阴虚者不可久伐。"}], "n": {"主痰湿内蕴": 7, "主痰热壅盛": 17, "主邪实壅盛": 1, "主食积内停": 6, "主风热郁遏": 3, "主气虚痰盛": 1, "主胃热上冲": 2, "相火亢盛": 1}, "a": {"2208": "主痰湿内蕴", "2415": "主痰热壅盛", "2416": "主痰热壅盛", "2740": "主痰热壅盛", "2741": "主痰热壅盛", "3501": "主食积内停", "4143": "主痰热壅盛", "6002": "主痰湿内蕴", "6028": "主痰热壅盛", "6057": "主痰热壅盛", "6143": "主痰热壅盛", "6186": "主食积内停", "6214": "主风热郁遏", "6296": "主食积内停", "6322": "主痰热壅盛", "6351": "主痰热壅盛", "6481": "主食积内停", "6509": "主风热郁遏", "7839": "主痰湿内蕴", "8145": "主胃热上冲", "8932": "主痰湿内蕴", "11459": "主痰热壅盛", "13019": "主痰热壅盛", "13457": "主痰热壅盛", "14122": "主痰热壅盛", "14264": "主胃热上冲", "14416": "主痰热壅盛", "14562": "主痰热壅盛", "15218": "主痰热壅盛", "17506": "主气虚痰盛", "18330": "相火亢盛", "18613": "主风热郁遏", "24795": "主痰湿内蕴", "24796": "主痰湿内蕴", "24832": "主痰湿内蕴", "24886": "主邪实壅盛", "24929": "主食积内停", "25070": "主食积内停"}, "t": 38, "np": 0}, "c:小+弱": {"o": "小弱脉总以虚为主，脉体收敛为小，搏动无力为弱，皆气血不充、阳气衰微之象。其类虽多，然核心病机不外阳气虚衰与气血两虚：阳虚则不能温煦固摄，见冷汗肢冷、下痢欲脱；气虚则不能充脉运血，见神疲心悸、经阻便难。脾胃虚寒、卫阳不足皆阳气虚之具体分属；正虚邪郁、虚阳上浮则为虚中夹实、本虚标热之变；胎元初结之小弱则属生理之常，非病脉。各证之间常相互兼夹，如气血两虚可兼脾胃虚寒，卫阳不足可兼正虚邪郁，临证当结合形症，辨其虚损所在与兼夹之邪，不可一概而论。", "c": [{"name": "主阳气虚衰", "desc": "小弱脉体收敛、搏动无力，为阳气不能充脉之象。原文见冷汗、手冷额冷、面色萎黄、精神不支，或下痢手足冷、阳虚欲脱，或胃中无阳、浊阴上僭，皆阳气大虚之征。"}, {"name": "主气血两虚", "desc": "小为脉道不充，弱为鼓动无力，主气血亏耗。原文见体质素虚、经阻而脉不见滑利，或久痢脱肛、神疲头晕心悸，或肠风日久、形瘦食少便难，皆气血不充之象。"}, {"name": "主脾胃虚寒", "desc": "小弱脉主脾胃气虚、阳气衰弱。原文见泄泻、两手俱冷、精神疲倦，或吐蛔、中焦虚寒，或食不加餐、四肢痹痛，皆脾阳不振、运化失职之候。"}, {"name": "主卫阳不足", "desc": "小弱为卫阳单薄、气衰之象。原文见长夏四肢痹痛、筋骨不舒，或右肢麻木不举、汗出麻冷，或老人气血不得宣通、麻木筋强，皆卫阳虚弱、络脉痹阻所致。"}, {"name": "主正虚邪郁", "desc": "小弱非纯虚，亦可为邪郁阳气、脉道不畅。原文见寒热初来脉形小弱，谓阳为邪郁，寒退自复；或暑伤气分、脉右小弱而芤虚；或伏邪伤正、阳气日漓，邪陷入阴。"}, {"name": "主虚阳上浮", "desc": "小弱示正虚为本，阴不恋阳则阳浮易动。原文见阳浮易动、从督脉上升、心中震荡惊惕，或右脉微数、三阴并亏而日萌痱中，皆虚阳上扰、根本不足之机。"}, {"name": "主胎元初结", "desc": "妇人平脉而阴脉小弱，为血养胎元、胞宫气血一时不足之象。原文见渴、不能食、无寒热，断为妊娠，小弱非病脉，乃胎气初结、阴血偏聚于下之常。"}], "n": {"主阳气虚衰": 7, "主气血两虚": 13, "主脾胃虚寒": 3, "主卫阳不足": 2, "主正虚邪郁": 6, "主虚阳上浮": 2, "主胎元初结": 1}, "a": {"627": "主气血两虚", "688": "主阳气虚衰", "693": "主脾胃虚寒", "703": "主气血两虚", "739": "主阳气虚衰", "740": "主气血两虚", "742": "主阳气虚衰", "758": "主气血两虚", "774": "主卫阳不足", "853": "主阳气虚衰", "1132": "主正虚邪郁", "1149": "主脾胃虚寒", "1161": "主气血两虚", "1238": "主气血两虚", "1303": "主正虚邪郁", "1546": "主卫阳不足", "1667": "主气血两虚", "4515": "主气血两虚", "8628": "主阳气虚衰", "10833": "主正虚邪郁", "11300": "主正虚邪郁", "11313": "主阳气虚衰", "14623": "主正虚邪郁", "15070": "主虚阳上浮", "15085": "主气血两虚", "16255": "主虚阳上浮", "16263": "主脾胃虚寒", "16279": "主气血两虚", "16289": "主气血两虚", "18546": "主气血两虚", "19619": "主气血两虚", "23706": "主阳气虚衰", "24463": "主正虚邪郁", "25441": "主胎元初结"}, "t": 34, "np": 0}, "pc:寸+滑+洪": {"o": "寸·滑洪脉总属痰、火、食积等实邪壅盛之象，以寸关部尤为明显。洪为火盛，滑为痰聚，合而主痰热壅盛、食积痰饮、郁火痰结、瘀血痰火等有余之疾。其病位多在上中二焦，涉及肺、胃、肝、心等脏腑。若兼尺脉沉伏或微弱，则形成上盛下虚、亢上不下之候，提示实邪壅于上而正虚于下。各类病机之间相互关联：痰热可与食积并存，郁火可致痰结，痰火久郁可成瘀血，而实邪壅盛日久又可耗伤下元，转为上盛下虚。故寸·滑洪脉虽以实热痰火为主，但须结合尺脉及兼脉，辨其有无下虚及瘀血等复杂病机。", "c": [{"name": "主痰热壅盛", "desc": "洪为火盛，滑为痰聚，寸关洪滑多主痰热壅于上中二焦。原文如“右寸关洪滑”断为肺经痰火，症见鼻塞、衄血、咽喉痰核；或“两寸洪滑”主痰火郁滞肺之气道，咳吐红痰；或“寸口洪滑”主痰火上攻肺胃，呃逆连声。皆因痰火胶结，脉道壅盛而现洪滑。"}, {"name": "主食积痰饮", "desc": "洪滑主实热痰积，寸关洪滑而尺沉伏，为食积痰饮内停肠胃之征。原文如“两手寸关洪滑，两尺沉伏”断为肠胃中有食积痰饮，症见五更倒饱、必泻一次、腹常作胀；或“右寸关脉洪滑，左脉弦”断为气郁食积痢。积滞内阻，气血壅滞于寸关，故脉洪滑。"}, {"name": "主上盛下虚", "desc": "寸脉洪滑而尺脉弱或沉微，为亢上不下、上盛下虚之候。原文如“两寸洪滑搏指，两关微弦，两尺微弱”断为溢脉，阳火上浮、真阴亏下；或“两寸脉皆洪滑，两尺弱”断为子悬，痰热壅上、下元不足；或“两寸洪滑，两尺沉微”主痰火壅盛于上、肾阳不足于下。"}, {"name": "主郁火痰结", "desc": "左寸关洪滑，右关亦然，主肝胆郁火、胃中胶痰。原文如“左寸关脉洪滑，右关亦然”断为肝胆有郁火、胃中有胶痰，症见胸胁胀痛、五更嘈杂，嘈杂则痛甚；或“左寸洪滑”主脾虚肝心二经火盛，痰火内扰。木火郁而犯胃，痰火互结，故脉洪滑。"}, {"name": "主瘀血痰火", "desc": "两寸洪滑，主瘀血痰火郁滞肺之气道，欲成肺痈。原文如“两寸脉洪滑”伴咳吐红痰如桃花脓色、前后心胀痛，断为瘀血痰火郁滞肺之气道；洪为火盛，滑为痰壅，痰火灼伤血络，气血壅滞，故脉洪滑。"}], "n": {"主痰热壅盛": 5, "主食积痰饮": 5, "主上盛下虚": 5, "主郁火痰结": 4, "主瘀血痰火": 2}, "a": {"3447": "主食积痰饮", "5995": "主上盛下虚", "6003": "主郁火痰结", "6025": "主食积痰饮", "6079": "主食积痰饮", "6134": "主上盛下虚", "6166": "主郁火痰结", "6190": "主上盛下虚", "6209": "主瘀血痰火", "6225": "主痰热壅盛", "6289": "主上盛下虚", "6297": "主郁火痰结", "6319": "主食积痰饮", "6373": "主食积痰饮", "6429": "主上盛下虚", "6461": "主郁火痰结", "6504": "主瘀血痰火", "6520": "主痰热壅盛", "8427": "主痰热壅盛", "18257": "主痰热壅盛", "24699": "主痰热壅盛"}, "t": 21, "np": 0}, "pc:关+滑+大": {"o": "关·滑大脉总以痰、火、食积、气滞等实邪壅盛于中焦为主，尤以痰火为核心。滑主痰饮，大主邪热，右关候脾胃，故脉见滑大有力多提示中焦痰火胶固、食积内停或气机壅滞。原文反复强调“中焦有痰，肝胆有火”“无痰不作晕”，症见眩晕、呕吐、咳喘、腹胀、眼赤肿痛等。若寸关滑大而尺部沉微，则属上盛下虚，痰火壅于上而肾元亏于下，为虚实夹杂。另有久疟后顽痰郁火、胃不和不得卧之痰多火少等，皆不离痰火食积范畴。诸类之间常相兼为患，痰可化火，食积生痰，气滞痰凝，总以中焦壅实为病机关键。", "c": [{"name": "主痰", "desc": "滑脉主痰，大脉主邪盛。原文多述“滑大有力主中焦痰盛”“滑主痰饮”，如眩晕呕吐、咳喘多痰、眼赤肿痛等症，皆因痰浊壅滞中上二焦，脉象滑大应之。"}, {"name": "主火", "desc": "大脉主火热亢盛，滑大有力为痰火相兼。原文谓“大主火”“肝胆火旺”“胃中湿热蒸燔”，症见发热面红、烦躁、吐血、便闭等，脉滑大有力示实火内炽。"}, {"name": "主食积", "desc": "滑主食积，大主积盛。原文有“胃中食滞”“气郁食积痰饮症”“食填太仓”等，症见腹胀、胃脘痛、嗳腐、便秘，右关滑大或沉实，为食积内停之征。"}, {"name": "主气滞", "desc": "滑大脉见于寸关，主气机壅滞。原文“血虚气滞症”“气郁食积痰饮症”，因忧思伤脾、气结不行，症见腹胀胁痛、气喘、面浮，脉滑大有力示气滞实证。"}], "n": {"主痰": 11, "主火": 3, "主食积": 5, "主气滞": 2}, "a": {"3899": "主痰", "4266": "主痰", "4302": "主痰", "6002": "主痰", "6057": "主痰", "6138": "主痰", "6143": "主痰", "6170": "主气滞", "6186": "主食积", "6214": "主火", "6296": "主食积", "6351": "主痰", "6433": "主痰", "6465": "主气滞", "6481": "主食积", "6509": "主火", "8145": "主火", "11459": "主痰", "11516": "主痰", "24929": "主食积", "25070": "主食积"}, "t": 21, "np": 0}, "c:滑+小": {"o": "小滑脉总属本虚标实、虚实夹杂之象。小主正气不足、阴血亏耗或阳虚，滑主痰湿、痰热、宿积或痰凝气滞。二者合参，常见于痰湿内蕴兼正虚、痰热内郁兼津伤、虚中挟实及痰凝气滞等证。其病机核心为正气已伤而痰湿（或痰热、食积）未化，虚为本、实为标。各段所主虽异，然皆不离‘小’示虚、‘滑’示实之总纲。如痰湿阻滞兼阳虚、痰热内郁兼津伤、久疟伤阴兼湿郁、汗衄后胃气尚存等，均体现虚实夹杂之特点。预后方面，小滑脉在汗衄后示胃气尚存，主生，亦不离正虚而邪不亢之机。", "c": [{"name": "主痰湿", "desc": "滑脉主痰湿内蕴，小滑脉中滑象明显，多因痰湿阻滞中焦或流注经络。原文如‘脉息耎滑而小’示痰湿阻滞，胸闷不欲食；‘脉象小滑，寒痰正盛’见舌强痹痛；‘滑则为痰’明言痰贮于肺。痰湿为标，脉滑应之。"}, {"name": "主正虚", "desc": "小脉主正气不足、阴血亏耗或阳虚。原文‘小则为虚’、‘小为阳虚不鼓’、‘小为营血不足’等，见产后阳虚、肺虚贮痰、营虚阴亏等。小滑脉中小象提示本虚，或气血阴阳不足。"}, {"name": "主痰热", "desc": "滑主痰，小示津伤或正虚，合为痰热内蕴。原文‘痰热阻滞为患’见谵语笑不休、舌尖红苔少；‘痰热内郁心包’见神识不清、舌苔白腻。痰热胶结，脉小滑为津伤痰热未净之候。"}, {"name": "主虚中挟实", "desc": "小滑脉常示虚实夹杂，正虚与痰湿、食积、外感等并存。原文‘病情虚中挟实’、‘营虚湿郁’、‘兼挟外感’等，见久疟伤阴兼湿郁、经讯淋漓兼外感。小为虚，滑为实，合为虚实夹杂之象。"}, {"name": "主痰凝气滞", "desc": "滑主痰，小示气机不畅，痰凝气滞阻于肺或经络。原文‘风寒闭肺，痰凝气滞’见喘不能卧、胸脘闷；‘湿痰攻注’见背俞脊庀作痛。痰凝气滞，脉小滑应之。"}, {"name": "主预后吉", "desc": "汗衄后阴血已伤，脉小滑示邪热不甚、胃气尚存，故主生。原文‘汗若衄，其脉小滑者，生’、‘小滑则邪热不甚、胃气尚存’，与小滑相对的大躁则死。小滑脉在此示正气未竭、胃气尚存。"}], "n": {"主痰湿": 4, "主正虚": 4, "主痰热": 4, "主虚中挟实": 3, "主痰凝气滞": 1, "主预后吉": 3}, "a": {"689": "主虚中挟实", "692": "主正虚", "757": "主痰热", "2869": "主痰热", "4690": "主痰湿", "5820": "主痰热", "8938": "主正虚", "10668": "主痰热", "11232": "主虚中挟实", "11625": "主虚中挟实", "11883": "主正虚", "15218": "主正虚", "15589": "主痰凝气滞", "15950": "主痰湿", "16829": "主痰湿", "18231": "主痰湿", "19216": "主预后吉", "21135": "主预后吉", "21824": "主预后吉"}, "t": 19, "np": 0}, "c:实+坚": {"o": "实坚脉总属邪实壅盛、正气未衰之象，其病机以“实”为核心。邪气包括水饮、痰浊、阳热、瘀血等，壅聚于里，脉道充实坚劲，故见实坚。此类脉多主暴病、新病，形气壮盛，可任攻逐苦寒。然实坚脉亦需参合胃气与形证：若脉实坚甚而失柔和，兼形气相失、色夭不泽、脉逆四时，则为胃气衰败、真脏脉见，病进难治。故实坚脉所主，一为邪实可攻之证，一为胃气败绝之候，关键在于脉有无胃气及与形证是否相应。各类之间，水饮、痰气、阳热、瘀血皆属邪实不同形态，而胃气衰败则为实坚脉之危重转归，须脉证合参以判吉凶。", "c": [{"name": "主邪实壅盛", "desc": "实坚脉为邪气亢盛、正气未衰之象。原文如“六脉坚实”主水饮暴停、邪实壅盛；脉坚体厚为阳实，能任苦寒；六脉坚实、人迎弹指主气郁成痰；右关硬欲搏指主有形实邪内结。皆因邪气壅聚，脉道充实而坚劲。"}, {"name": "主水饮内停", "desc": "水饮暴停，邪实于里，脉见坚实。如何氏夏月饮水十余碗，胀如抱瓮、气高而喘，六脉坚实，法当峻下逐水；又山右何宗鲁证同，脉坚实为邪实内结，水湿内停，暴病脉实，正气未虚，故可攻逐。"}, {"name": "主痰气郁结", "desc": "气郁成痰，痰气交阻，脉见坚实弹指。如郭梦槐妻抱郁而病，胸膈满闷、胃气增痛，六脉坚实、人迎尤弹指，为气郁成痰、胃失和降；胃脘痛脉坚实者属实证可下，亦痰食实结之征。"}, {"name": "主阳热内实", "desc": "阳热内实，肝风升腾，脉坚体厚。如马香谷溺秘欲死，脉坚体厚、口渴苔黄，孟英谓“脉坚则阳实，阳实则能任苦寒”，投苦寒直折肝经实火而愈。实坚脉示阳热壅盛，可任苦寒攻下。"}, {"name": "主胃气衰败", "desc": "脉实以坚，失柔和胃气，为真脏脉独见之兆。原文以“脉弱以滑”为有胃气，“脉实以坚”为无胃气、邪气益甚，病进难治；形气相失、色夭不泽、脉实坚甚且逆四时者，皆胃气衰败、预后不良之候。"}, {"name": "主瘀血坠伤", "desc": "瘀血内结或坠伤，脉可坚实。如肝脉搏坚而长，色不青，当病坠，瘀血在胁下；瘀血腹胀脉坚强者生，小弱者死。实坚脉示瘀血有形之邪内结，脉病相应则生，反之则危。"}], "n": {"主邪实壅盛": 6, "主水饮内停": 2, "主痰气郁结": 1, "主阳热内实": 1, "主胃气衰败": 8, "主瘀血坠伤": 1}, "a": {"3740": "主水饮内停", "14164": "主阳热内实", "17286": "主痰气郁结", "17300": "主邪实壅盛", "17392": "主水饮内停", "18665": "主邪实壅盛", "19200": "主邪实壅盛", "21102": "主胃气衰败", "21818": "主胃气衰败", "21819": "主胃气衰败", "21824": "主邪实壅盛", "22764": "主胃气衰败", "22765": "主邪实壅盛", "23233": "主胃气衰败", "23242": "主胃气衰败", "23394": "主邪实壅盛", "23703": "主胃气衰败", "23712": "主胃气衰败", "24075": "主瘀血坠伤"}, "t": 19, "np": 0}, "pc:右+弦+虚": {"o": "右·弦虚脉总以右虚左弦为特征，右虚主脾胃中气不足，左弦主肝木偏旺或肝风内动。其病机核心为脾虚肝乘，即土虚木贼，涵盖脾虚肝乘、中虚肝风、脾虚湿滞、肝旺脾弱、气阴两虚、气虚痰湿、肝风犯胃等类。各类之间相互关联：脾虚为本，肝旺为标，湿滞、痰湿、风动皆由虚而生，气阴两虚则虚风内动。总属本虚标实、肝脾失调之候，治当培土制木、柔肝熄风、健脾化湿，随证施治。", "c": [{"name": "主脾虚肝乘", "desc": "右脉虚主脾胃气虚，左弦主肝木偏旺，肝木乘土。原文如“右虚左弦，不思饮食，脾胃困顿”“脉右虚左弦，中虚肝气内动”“左弦右虚，中伤何疑”，皆示脾虚而肝乘之病机。"}, {"name": "主中虚肝风", "desc": "右虚为中气不足，左弦为厥阴内风暗动。原文如“脉右虚左弦，身麻肢冷，胎冲胀闷”“脉弦右虚，肝风内震，心惕头晕肢战”，皆因虚而风动，非实火亢盛。"}, {"name": "主脾虚湿滞", "desc": "右脉虚弦，虚为脾土不足，弦为湿郁气滞。原文如“右脉虚弦，服温剂色黄更甚，黄为土之正色，因湿外现”“脉右虚弦，肺气亏而中气虚，咳嗽痰稠”，皆脾虚不运、湿滞内停之象。"}, {"name": "主肝旺脾弱", "desc": "左弦为肝旺，右虚为脾弱，木旺乘脾犯胃。原文如“久疟致肝木阴亏阳旺，木旺则乘脾犯胃，脉左弦右虚”“脉右虚左弦，肝脾两亏，湿热下注”，皆肝旺脾弱、中伤失运之机。"}, {"name": "主气阴两虚", "desc": "右脉虚软或虚弦，左脉虚弦，示脾肺气阴不足，肝木乘虚而亢。原文如“右虚软，左脉虚弦，面白无神，盗汗淋漓，气逆痰稠”“右寸短涩，关虚小滑，左关虚弦，水少于火”，皆气阴亏虚、阴阳未平之候。"}, {"name": "主气虚痰湿", "desc": "右脉滑疾无力或虚滑，左脉虚弦，为气虚有痰，脾虚生湿，肝虚生风。原文如“右脉滑疾无力，左脉虚弦，气虚有痰，肝虚生风，脾虚生湿”“右脉虚滑，左脉虚弦，脾阳不运，湿痰内停”，皆气虚痰湿内阻之病机。"}, {"name": "主肝风犯胃", "desc": "脉虚弦，右关见弦，为肝风犯胃、胃气不和。原文如“头晕心悸，脉虚右弦，此肝风犯胃，癸水不调”“脉弦右虚，肝风内震，心惕头晕”，皆肝风扰动、胃失和降之象。"}], "n": {"主脾虚肝乘": 2, "主中虚肝风": 3, "主脾虚湿滞": 1, "主肝旺脾弱": 4, "主气阴两虚": 2, "主气虚痰湿": 4, "主肝风犯胃": 1}, "a": {"1125": "主脾虚肝乘", "1773": "主中虚肝风", "4974": "主中虚肝风", "6643": "主脾虚湿滞", "10498": "主肝旺脾弱", "11702": "主肝旺脾弱", "12826": "主气虚痰湿", "12827": "主气虚痰湿", "15496": "主气阴两虚", "15542": "主气阴两虚", "15577": "主气虚痰湿", "15669": "主脾虚肝乘", "15742": "主气虚痰湿", "15869": "主肝旺脾弱", "15923": "主肝旺脾弱", "16882": "主中虚肝风", "17147": "主肝风犯胃"}, "t": 17, "np": 0}, "pc:尺+大+洪": {"o": "尺·大洪脉总属阳热亢盛之象，但所主病机因兼脉与部位而异。洪大而数者主热毒炽盛；洪大兼滑者主痰火壅盛；洪大有力独见于尺者，或为相火亢盛，或为胎孕气血充盛；洪大与沉微并见，则属上盛下虚、阳亢阴微；若尺涩而肺脉洪大无伦，又为水气上壅、下闭上壅之候。诸类之间，以热盛、痰火、相火为实热壅盛之直接表现，孕脉为生理性气血充盛，上盛下虚与水气上壅则属虚实夹杂、上下失调之变。总以洪大为阳热亢盛之基，兼脉兼症不同，故有实热、痰火、相火、胎孕及虚实夹杂之分。", "c": [{"name": "主热盛", "desc": "尺脉洪大而数，为热邪炽盛之象。原文如杨梅疮毒内陷案，六脉俱洪大而数，断为热毒炽盛、气血壅滞；又有积热三消，尺脉洪大主下消，右脉数大主肠胃积热，皆因洪大为阳热亢盛，数则热急，故主实热壅盛之病机。"}, {"name": "主相火", "desc": "尺脉洪大，为下焦相火亢盛之征。原文论苦寒泻膀胱相火，谓尺脉洪大示相火不藏、湿热下注，症见骨蒸劳热、诸痿瘫痪、目赤耳鸣、消渴黄疸。相火妄动，煎熬阴液，故脉洪大有力，主相火偏亢之病机。"}, {"name": "主孕", "desc": "尺脉洪大有力，为孕脉之特征。原文戴人诊妇人孕，六脉皆平，惟右尺洪大有力，断为孕；又引《素问》阴搏阳别之脉，尺候胞宫，孕则气血充盛，故洪大搏指。虽症似干血气，脉象为辨孕关键，主胎孕气血壅盛之病机。"}, {"name": "主上盛下虚", "desc": "尺脉洪大与沉微并见，为上盛下虚之候。原文吴双泉案，两尺洪大而沉微，洪大主痰火壅盛于上，沉微主肾阴不足于下，阳亢阴微，上实下虚。症见头目不清、腰膝酸软，法当清上补下，主阴阳失调、上盛下虚之病机。"}, {"name": "主水气上壅", "desc": "尺脉微涩而肺脉洪大无伦，为下焦阴血不足、水气太过上壅。原文喻嘉言案，尺涩示下焦血虚，肺洪大示水气太过、肺失肃降，上壅会厌胸膈，症见食入痛楚、喘声如锯。洪大无伦与尺涩并见，主下闭上壅、气血逆奔之病机。"}, {"name": "主脏气败绝", "desc": "脉见屋漏、雀啄、弹石、解索等怪脉，无胃气柔和之象，为脏气败绝、真元离散之死候，脉病人不病者尤凶。"}], "n": {"主热盛": 7, "主相火": 1, "主孕": 3, "主上盛下虚": 2, "主水气上壅": 1, "主脏气败绝": 1}, "a": {"4040": "主水气上壅", "6194": "主热盛", "6239": "主上盛下虚", "6489": "主热盛", "6532": "主上盛下虚", "18419": "主热盛", "19143": "主孕", "19146": "主孕", "19149": "主孕", "21823": "主脏气败绝", "21824": "主热盛", "23815": "主热盛", "23979": "主热盛", "24910": "主热盛", "26182": "主相火"}, "t": 15, "np": 0}, "pc:左+细+小": {"o": "左脉细小总属不足之象，主阴血精津亏虚，其病机以虚为本。从所收14段看，或见于血崩后血舍空虚，或见于伏暑化火伤阴，或见于精浊梦遗精血内亏，或见于肝肾虚胀之肝经、肾经不足，皆以细小示脉道不充、阴血亏少。在此基础上，可兼见虚阳不能敛纳而上冲，如动气心悸；可兼真阴不足、肝木失养而顺乘中土，如干哕不思纳；可兼气虚不摄、湿热浑窍而精关不固；亦可与右脉弦数、洪大并见，形成阴伤火旺、少阴不足阳明有余之虚实夹杂证。要之，左脉细小以阴血精津亏虚为主线，诸类或为直接虚损，或为虚中夹实、虚阳浮越、木乘土位等衍生之机，总不离“不足”二字。", "c": [{"name": "主阴血亏虚", "desc": "左脉细小多主阴血不足。如血崩后左脉细小、心脉尤弱，为血舍空虚；左脉细小、尺如绵，为精血久亏；左关细小主肝经不足，左尺细小主肾经不足。细小之脉示脉道不充，阴血亏少，故主阴血虚。"}, {"name": "主真阴不足", "desc": "左脉细小无神，主真阴亏虚。如伏暑化火伤阴，左脉细小按之无神，为真阴不足；阴津大伤，左脉细小，为少阴阴伤。真阴耗损，脉道失充，故细小无神。"}, {"name": "主气虚不摄", "desc": "左脉细小亦主气虚。如左手细小、右手带数，无梦而遗，为气虚不摄、湿热浑窍；左脉细小难寻，胸腹俱痛，为气血不畅。气虚无力鼓动，脉道不充，故细小。"}, {"name": "主虚阳上浮", "desc": "左脉细小而兼他部弱，可见虚阳不能敛纳。如左脉细小、心脉尤弱，脐左动气上冲、心悸多汗，为血舍空虚、虚阳不能敛纳；右部软大无力、左关弦细、尺细小难寻，为血室空虚、虚阳外浮。阴血亏虚，阳失涵养，故虚阳上浮。"}, {"name": "主肝木犯土", "desc": "左脉细小无神兼关部带弦，主真阴不足、肝木失养而犯土。如左脉细小无神、关部带弦，真阴不足难以涵养肝木，肝木顺乘中土，症见不思纳、干哕恶心。阴亏肝旺，木乘土位，故主肝木犯土。"}, {"name": "主精血内亏兼湿热", "desc": "左脉细小与右脉弦数并见，主精血内亏兼湿热。如精浊日久、梦遗见血，左脉细小、右脉弦数，为精血内亏、湿热所伤；左手细小、右手带数，舌苔黄腻，为气虚不摄、湿热浑窍。正虚邪恋，虚实夹杂。"}], "n": {"主阴血亏虚": 3, "主真阴不足": 7, "主气虚不摄": 1, "主虚阳上浮": 1, "主肝木犯土": 1, "主精血内亏兼湿热": 1}, "a": {"687": "主阴血亏虚", "4669": "主真阴不足", "4670": "主真阴不足", "9055": "主精血内亏兼湿热", "9092": "主真阴不足", "9093": "主肝木犯土", "10825": "主真阴不足", "11123": "主气虚不摄", "13526": "主真阴不足", "14580": "主真阴不足", "15682": "主阴血亏虚", "15816": "主阴血亏虚", "15922": "主虚阳上浮", "24888": "主真阴不足"}, "t": 14, "np": 0}, "e:结": {"o": "结脉总属脉气不相接续之象，其病机以气血痰食等阻滞脉道为主，兼有正虚不续。归纳其主病，一为气滞，气机壅塞则脉结；二为痰饮，痰饮结聚阻遏脉道；三为血瘀，瘀血内停脉行不畅；四为正虚，气血亏虚脉气不继；五为邪结，外邪痰食毒气结于胸中或经络；六为寒凝，阴寒内盛凝滞气血；七为热结，实热壅滞气机。诸类之间，气滞、痰饮、血瘀、邪结、寒凝、热结多属邪实阻滞，脉结因脉道不利而止无定数；正虚则因气血衰少、脉气不续而结。实者宜通，虚者宜补，虚实夹杂者当辨其主次。结脉虽为病脉，然止无定数，病较轻浅，与代脉之止有定数、脏气衰微者不同，预后多良。", "c": [{"name": "主气滞", "desc": "结脉止无定数，为气机阻滞、脉道不利之象。原文如“六脉见结，此气滞也”，以行气而愈；又“脉症气结在上”“脉气壅结”等，皆因郁怒气壅、痰气交阻，致脉气结而不畅，故主气滞。"}, {"name": "主痰饮", "desc": "结脉主痰饮结聚，阻遏气机。原文“支脉结饮”致喘胀胁痛眩冒，“块痰寒滞经脉隧道”而六脉俱结，“寒湿痰凝滞、阳气不伸”见脉结，皆痰饮寒湿壅塞脉道，故脉结。"}, {"name": "主血瘀", "desc": "结脉主血行瘀滞、脉络不通。原文“经脉结聚不调，腹中撮痛”“血脉中热结”“脉络结濇”及“瘀热互结下焦”之蓄血，皆因瘀血内阻，脉道不利而结，故主血瘀。"}, {"name": "主正虚", "desc": "结脉主气血虚衰、心气不足。原文“病发而脉结者，血少气劣耳”“脉结悸”属虚劳，“脉结止，苏则如常，但浮虚”为气血两虚，皆因气血亏虚、脉气不续而结，故主正虚。"}, {"name": "主邪结", "desc": "结脉主邪气结聚胸中或经络。原文“脉乍结，以客气在胸中”致厥冷烦满，“毒气壅于肌肉”见结脉寒热如瘰疬，皆外邪、痰食、毒气结聚，阻遏脉道，故主邪结。"}, {"name": "主寒凝", "desc": "结脉主阴寒内盛、寒凝气滞。原文“脉沉而迟……名曰阴结”，为寒凝太阴；“寒痰凝结、瘀塞经络”见迟濡而结；“中气虚寒，络脉结滞”亦脉结，皆寒邪凝滞、阳气不伸所致。"}, {"name": "主热结", "desc": "结脉主实热内结、壅滞气机。原文“脉浮而数……名曰阳结”，为阳明实热；“脉洪实异常……乃结脉”因外感实热壅滞；“血脉中热结”亦致脉结，皆热邪结聚、脉道不利，故主热结。"}, {"name": "治法类", "desc": "述外治内服诸法，如锋针泻血、敷药内消等，非凭脉断病，脉象要素不显，故别为一类。"}, {"name": "比类取象", "desc": "以自然物象比喻经脉循行与气血津液，非论脉诊，属比类取象之文，脉象要素为空。"}, {"name": "篇目提示", "desc": "仅标篇章题名，未展开脉象与病机论述，无从归类于具体病机，故单列篇目提示。"}, {"name": "药性病机", "desc": "论药性升降与病机逆上，如半夏辛泄滑降治气逆，未及脉象，属药性病机类。"}, {"name": "本草考证", "desc": "为本草药物考证，述药性、采收、形态及主治，非脉学原文，脉象要素为空，属本草考证类。"}], "n": {"主气滞": 10, "主痰饮": 14, "主血瘀": 10, "主正虚": 16, "主邪结": 12, "主寒凝": 6, "主热结": 12, "治法类": 1, "比类取象": 1, "篇目提示": 1, "药性病机": 1, "本草考证": 1}, "a": {"1371": "主痰饮", "1373": "主痰饮", "1374": "主痰饮", "1375": "主痰饮", "3538": "主正虚", "3708": "主痰饮", "3796": "主气滞", "4026": "主气滞", "4482": "主正虚", "4888": "主痰饮", "4901": "主正虚", "5235": "主痰饮", "5253": "主痰饮", "5483": "主邪结", "5517": "主痰饮", "5546": "主邪结", "6233": "主寒凝", "6526": "主寒凝", "8307": "主热结", "8375": "主热结", "8608": "主气滞", "10432": "主热结", "11309": "主血瘀", "12160": "主气滞", "12243": "主寒凝", "12532": "主气滞", "12533": "主气滞", "15255": "主痰饮", "15291": "主正虚", "17333": "主痰饮", "18536": "主痰饮", "18656": "主热结", "18723": "主热结", "18888": "主血瘀", "19029": "主邪结", "19076": "主邪结", "19575": "主寒凝", "19746": "主热结", "19843": "主血瘀", "20021": "主气滞", "20026": "主热结", "20027": "主热结", "20031": "主热结", "20378": "主正虚", "20379": "主正虚", "20382": "主正虚", "21019": "主正虚", "21394": "主邪结", "21717": "主邪结", "21751": "主寒凝", "21797": "__np", "21993": "主邪结", "22027": "主气滞", "22080": "主血瘀", "22202": "主邪结", "22210": "治法类", "22311": "主热结", "22425": "主气滞", "22669": "主正虚", "22793": "主正虚", "22927": "主邪结", "23022": "主气滞", "23723": "主邪结", "24175": "主血瘀", "24181": "主邪结", "24253": "主痰饮", "25285": "主正虚", "25286": "主正虚", "25736": "主正虚", "25741": "主正虚", "25845": "比类取象", "25849": "主热结", "25892": "主血瘀", "25929": "主血瘀", "25952": "主邪结", "26500": "篇目提示", "26946": "主寒凝", "26965": "主血瘀", "26966": "主热结", "26976": "药性病机", "26988": "主正虚", "27168": "主血瘀", "27347": "__np", "27589": "主正虚", "27656": "主血瘀", "27847": "主痰饮", "27968": "本草考证"}, "t": 87, "np": 2}, "pe:右+缓": {"o": "右缓脉总属湿困气分、脾胃不健之象，因右脉候气、候脾胃，缓主湿滞，故湿邪阻遏气机、脾运不健者多见右脉缓。然缓脉有常变之分：病中右缓而兼滞、兼软弱，多主湿阻、脾虚、食湿壅滞，甚则湿热入络、血虚风动；若病后右脉转缓而诸恙向安，则为胃气来复、向愈之征。诸类之间，以湿阻气分为核心，湿困则脾运不健，久则化热入络，或兼食滞、肝郁，或耗伤气血而风动；而胃气来复之缓，乃邪退正复之转归，与病脉之缓虚实迥异。故右缓脉所主，当结合兼脉、病程及症状，辨其湿、虚、滞、复之不同。", "c": [{"name": "主湿阻", "desc": "右脉缓多因湿邪黏滞，阻遏气机，脉道弛缓。原文如“湿著阻气”“秽湿著里，邪阻气分，舌白滑，脉右缓”，及“右脉见缓之故，知气分之湿阻”，皆以右候气分，缓为湿困之象，症见身重、脘闷、舌白滑等。"}, {"name": "主脾虚", "desc": "右脉候脾胃，缓而软弱为脾胃气弱、正气不足之征。如“右脉软弱”见于阳明少阳并病，示正气已伤；又“左脉尚缓，右脉尚大”谓缓为胃气尚存，说明脾胃未至大衰，故缓脉可反映脾虚气弱。"}, {"name": "主湿热入络", "desc": "湿邪久羁，化热入络，脉右缓左实。原文“湿热混处血络之中，搜逐甚难”，因湿性黏滞故右脉缓，热结血络故左脉实，症见内踝重著、发斑、筋掣，久则化热烁血、风动舍于肝胆，属湿痹之症。"}, {"name": "主血虚风动", "desc": "右脉缓而瘫麻木，非平人之和缓，乃血虚不充、筋脉失养，兼寒凝风动之象。原文“脉缓男子右瘫麻木，丹溪议从血虚有风”，起病值冰雪寒威，寒伤营血，故脉缓示血虚风动兼寒凝，治以舒筋汤养血祛风。"}, {"name": "主食湿壅滞", "desc": "右脉滞而缓，滞为气机壅滞，缓为湿困中焦，兼左关微弦为肝郁。原文“怒动肝火，阴络内伤，兼之中焦挟食”，症见疟热、便血，脉右滞缓示中焦食湿壅滞，肝火犯络，故以柴胡、楂肉、木香等疏肝运脾。"}, {"name": "主胃气来复", "desc": "病后右脉转缓，为胃气和调、湿热渐化、药证相合之向愈征象。原文“诸恙向安，右脉亦缓。药能应手，何其速也”，前诊脉数疾弦滑，今右脉缓，说明胃气来复，故判断预后良好，再守原法。"}], "n": {"主湿阻": 3, "主脾虚": 3, "主湿热入络": 2, "主血虚风动": 1, "主食湿壅滞": 1, "主胃气来复": 2}, "a": {"1320": "主湿阻", "1556": "主湿热入络", "4484": "主湿热入络", "5850": "主胃气来复", "6248": "主脾虚", "6541": "主脾虚", "8548": "主血虚风动", "10436": "主食湿壅滞", "10692": "主胃气来复", "12618": "主脾虚", "24448": "主湿阻", "24449": "主湿阻"}, "t": 12, "np": 0}, "c:数+滑+大+洪+长": {"o": "滑数洪大长脉总起来主热盛、心火亢盛及阳气外浮三类病机。原文以夏月为例，阐明一身之气随四时五运六气兴衰，夏月心火生而热，故脉见滑数洪大而长，伴烦热多渴，绝非寒象。滑数主热邪内盛，洪大而长主心火亢盛、阳气外浮，三者相互关联：热盛为病机基础，心火亢盛为具体脏腑定位，阳气外浮为时令性生理病理表现。三类病机均围绕“热”与“阳”展开，共同揭示脉象与四时气候、脏腑功能的内在联系，强调脉候随气运兴衰而变化，不可拘泥于冬夏寒热之俗说。", "c": [{"name": "主热盛", "desc": "滑数脉象直接反映热邪亢盛。原文指出夏月心火生而热，脉见滑数，滑主痰食积滞化热，数主热象急迫，故滑数并见为热盛之征，结合烦热多渴，明确提示热邪内盛。"}], "n": {"主热盛": 1}, "a": {"25123": "主热盛"}, "t": 1, "np": 0}, "c:数+沉+浮+迟": {"o": "浮沉迟数四脉为脉诊提纲，总括表里寒热虚实之辨。浮脉主表，有力为邪搏，无力为虚；沉脉主里，沉健主积滞，沉弦主气病，沉迟有力主疼痛；迟脉主寒，数脉主热，迟数相兼可辨疟之寒热、胃之冷温。四脉虽简，却能统摄外感内伤诸多病机：浮以候表，沉以候里，迟以候寒，数以候热，再参有力无力以分虚实。诸类之间，表邪与虚证皆见于浮，寒热见于迟数，积滞、气病、疼痛见于沉，风涎见于浮缓，彼此交织，构成脉诊辨证之基础。", "c": [{"name": "主表邪", "desc": "浮脉主表，为邪在肌表之象。原文'浮而有力为邪所搏'，又'浮大伤风兮浮紧伤寒'，说明浮而有力主外邪侵袭，浮大主伤风，浮紧主伤寒，皆属表证范畴。"}], "n": {"主表邪": 2}, "a": {"8296": "__np", "12167": "主表邪", "22818": "主表邪"}, "t": 3, "np": 1}, "c:数+弦+滑+小": {"o": "小弦滑数脉总起来主阴虚正虚、邪郁、痰热内盛，并有热极生风之变。脉小为阴虚正虚，弦为邪郁，滑数为痰热。四者相合，反映正虚不能载邪外达，而痰热仍炽，形成正虚邪实、本虚标实之局。其中阴虚正虚为本，痰热邪郁为标，标实进一步可致热极生风、痉厥变幻。诸类病机相互关联，虚、郁、痰、热并存，提示病情复杂，需兼顾扶正与祛邪。", "c": [{"name": "主阴虚正虚", "desc": "脉小为阴虚正虚之象。原文见舌光绛无苔、白㾦空壳无神，乃阴液亏耗、正气不足，不能载邪外达，故脉形偏小。"}], "n": {"主阴虚正虚": 1}, "a": {"2412": "主阴虚正虚"}, "t": 1, "np": 0}, "pc:六+弦+滑+大+浮": {"o": "六·弦滑大浮脉总属风痰壅盛、阳热内扰之候。浮主风邪外袭，大主阳热亢盛，弦主肝风内动，滑主痰湿内蕴，四者相合，反映风、热、痰、湿交结为患。原文载“六脉浮大弦滑，右甚于左”，右属气分，右甚于左提示病位偏于气分，痰湿壅盛于上。患者身肥白，素多痰湿，春初风木当令，风邪引动肝风，挟痰上扰，蒙蔽清窍，故见暴仆不知人事、口噤不语、喉如拽锯等症。四类病机相互关联：风邪外袭引动肝风，肝风内动又挟痰湿上扰，阳热亢盛则鼓动气血，使痰湿更易壅滞。总以风痰壅盛为核心，阳热为兼夹，故治疗以吐痰开窍为先，继以续命汤发汗祛风，使风痰得解，阳热得清。", "c": [{"name": "主风邪", "desc": "脉浮为风邪外袭之象。原文载“六脉浮大弦滑”，浮脉主表，风邪犯卫，故见暴仆、口噤等中风卒倒之症。春初风木当令，风邪引动内风，上扰清窍，故浮脉为风邪外中之据。"}], "n": {"主风邪": 1}, "a": {"3280": "主风邪"}, "t": 1, "np": 0}, "c:弦+沉+浮+涩": {"o": "浮弦沉涩脉总起来主风、湿、瘀相互搏结之病机。浮弦为风动之象，沉涩为湿滞血瘀之征，二者并见，说明外风引动内湿，湿浊与瘀血相结，形成湿瘀互结之候。原文产妇新产，气血未复，湿浊内蕴，瘀血未净，风动于上，故见发搐、气喘、面黑、口臭等症。丹溪断为受湿，治以化湿行瘀，下瘀块后愈，证实湿瘀互结为病机关键。四类中，主风、主湿滞、主血瘀分别从不同脉位与脉象特征归纳，而湿瘀互结则统括复合脉象的整体病机，诸类相互关联，共同反映风、湿、瘀交织为患的特点。", "c": [{"name": "主风", "desc": "浮弦脉主风。原文脉浮弦，浮为在表，弦主风动，故见产后发搐、气喘等症。丹溪以浮弦为风象，结合他症辨为风动之机。"}], "n": {"主风": 1}, "a": {"4074": "主风"}, "t": 1, "np": 0}, "c:弦+细+沉+弱": {"o": "沉细弦弱脉总属阴脉，主虚与饮两类病机。沉细弱主虚，反映阳气不足、气血亏虚；弦主饮，反映饮邪内伏。二者相合，说明饮为阴邪、阳气不足，本虚标实。原文强调‘最忌补阴，补阴必死’，因饮为阴邪，补阴则助阴碍阳，故当以温化饮邪为治。虚与饮相互关联，阳虚是饮停的基础，饮停又进一步耗伤阳气，形成恶性循环。", "c": [{"name": "主虚", "desc": "脉沉细弱，沉主里，细弱主虚，为阳气不足、气血亏虚之象。原文谓‘沉细弱主虚’，且‘脉为阴脉’，说明正气内虚，尤以阳虚为主，故见沉细弱之阴脉。"}], "n": {"主虚": 1}, "a": {"5511": "主虚"}, "t": 1, "np": 0}, "c:数+细+急+促": {"o": "细数急促脉总起来主阴伤火旺，兼涉湿热痰浊与络损血溢。其核心病机为阴液亏虚、虚火内炽，脉细为阴伤，数为热，急促为火势急迫。在此本虚标实基础上，可因湿热久滞、痰浊内蕴而兼右关弦滑；火旺灼伤血络，则见吐血，形成络损血溢之变。三者相互关联：阴伤火旺为根本，湿热痰浊为兼邪，络损血溢为火旺所致出血之果。脉症合参，提示病机复杂，虚火、湿热、出血并存，但以阴伤火旺为主线。", "c": [{"name": "主阴伤火旺", "desc": "脉细数急促，细为阴血不足，数为热，急促为火势急迫。原文述吐血后血去阴伤，金水不能相生，风邪化火，肾水亏、肺金损，故脉见细数急促，主阴液耗伤、虚火内炽。"}], "n": {"主阴伤火旺": 1}, "a": {"7460": "主阴伤火旺"}, "t": 1, "np": 0}, "pc:左+弦+细+滑+微": {"o": "左弦细滑微脉总起来主阴血不足、肝火偏动、湿痰阻胃、阴阳不交之病机。细为阴血亏虚，左关微弦为肝火内动，右关带滑为胃中湿痰。三者相合，湿痰借肝火鼓动而阻梗胃府，使心肾水火相交之路不通，遂成阴阳不交之不寐。四类病机中，阴血不足为本，肝火偏动为动因，湿痰阻胃为关键，阴阳不交为结果，层层相因，共同构成该脉所主之证候。", "c": [{"name": "主阴血不足", "desc": "脉细为阴血亏虚之象。原文谓“细为阴血不足”，阴血虚则脉道不充，故脉体细小。此段脉细与左关微弦、右关带滑并见，提示阴血不足为不寐之基础病机之一。"}], "n": {"主阴血不足": 1}, "a": {"7971": "主阴血不足"}, "t": 1, "np": 0}, "c:数+细+滑+大": {"o": "细数滑大脉总属虚实夹杂之象。细数主阴液亏虚、邪火内炽，滑大主痰热壅盛。四类病机相互关联：阴液亏虚则水不济火，邪火内炽则灼阴生痰，痰热壅盛又进一步耗伤气阴，形成正虚邪恋之势。原文“气阴略立定，邪火又复上炎”点明正虚与邪火并存，脉见细数中兼滑大，提示正不敌邪，病情有猝变之虞。故本脉所主以阴虚火旺、痰热内蕴为基础，进而表现为正虚邪恋的复杂病机。", "c": [{"name": "主阴液亏虚", "desc": "脉细数主阴液不足。原文谓“气阴略立定”，脉左细数，舌干绛密刺，唇燥裂起腐，皆阴液亏耗、水不济火之象。细为阴血不足，数为虚热内生，故细数脉主阴液亏虚。"}], "n": {"主阴液亏虚": 1}, "a": {"9696": "主阴液亏虚"}, "t": 1, "np": 0}, "pc:右+数+细+滑+小": {"o": "右寸数细滑小脉总起来主肺脏病变，以伏火挟痰为核心，兼见阴伤气结。数脉主伏火，细脉主阴伤，滑脉主痰，小脉示气机郁结。四者相合，反映肺阴不足、伏火内炽、痰浊内蕴、气机郁结的复合病机。原文以右寸候肺，结合悲思、纳减、睡醒特甚等症，断为伏火挟痰，并指出惊恐可致气结成痹，升降失常，胃气日馁。各类病机相互关联：阴伤为伏火之基，伏火炼液成痰，痰阻气机则气结，气结又加重阴伤与火郁，形成恶性循环。", "c": [{"name": "主伏火", "desc": "脉数主热，细为阴伤，右寸候肺，肺阴不足则伏火内生。原文'右寸细数而小滑'，数脉为伏火之征，火郁于肺，故见竟日悲思、睡醒特甚等症。"}], "n": {"主伏火": 1}, "a": {"10901": "主伏火"}, "t": 1, "np": 0}, "c:弦+细+滑+沉": {"o": "弦滑沉细脉总起来主肝胆郁滞、痰饮内聚与里阳虚损三类病机，三者相互关联，形成本虚标实之证。弦滑主肝胆气郁、痰饮内聚，为病之标；沉细主阳虚于里，为病之本。原文以惊恐伤胆、抑郁动肝、思虑伤脾为起病之由，肝胆郁则气机不畅，脾阳不运则谷食不化变蒸为痰，痰饮袭于奇经、溢于四末，致肩井如折、肢体麻木、咳逆气促等症。弦滑与沉细并见，正合“始于肝胆、中于痰饮、终于阳虚”之论，体现体虚症实、本虚标实之病机特点。", "c": [{"name": "主肝胆郁", "desc": "脉弦滑为肝胆气郁之象。原文载惊恐伤胆、抑郁动肝，情志不遂致肝胆气机郁滞，弦脉应肝胆，滑脉示气郁生痰，故弦滑并见主肝胆郁滞、气机不畅。"}], "n": {"主肝胆郁": 1}, "a": {"11060": "主肝胆郁"}, "t": 1, "np": 0}, "c:数+滑+微+小": {"o": "微小滑数脉总起来主阳虚阴盛、下焦不固、虚阳不藏之证。脉微小为阳气衰微、阴寒内盛之象，滑数则非实热，而是下焦不固、虚阳不藏所致。原文“上中下三部阳虚阴盛”点明病机根本为阳气虚衰、阴寒内盛，故虽见齿痛剧烈、恶热饮等似热之症，实为阳虚阴盛、虚阳浮越之假热。三类病机相互关联：阳虚阴盛为本，下焦不固为阳虚不能固摄之果，虚阳不藏为阴寒内盛、格阳于外之变。临证当脉证合参，勿以滑数为热而误清，当温阳散寒、固摄下焦。", "c": [{"name": "主阳虚阴盛", "desc": "脉微小为阳气衰微、阴寒内盛之象，原文谓“上中下三部阳虚阴盛”，故脉微小主阳气虚衰、阴寒内盛，属本虚寒盛之候。"}], "n": {"主阳虚阴盛": 1}, "a": {"19273": "主阳虚阴盛"}, "t": 1, "np": 0}, "c:数+细+沉+小": {"o": "沉细小数脉总起来主里虚有热、正虚邪恋之证。沉主里，细主虚，小主不足，数主热，四者相合，揭示病位在里、正气虚衰而兼有热象。从原文看，该脉见于夏月暴冷伤中、泄痢耗液之后，正虚水湿不化，通身浮肿，成冷下结。其病机核心是里虚有热，正虚邪恋，水湿内停。各类之间相互关联：里虚是基础，虚而水湿不化则内停，水停气阻又成冷下结，而数脉所主之热与虚并存，形成虚实夹杂之局。故临床见沉细小数脉，当考虑正虚邪恋、水湿内停、寒热错杂之病机。", "c": [{"name": "主里虚", "desc": "沉脉主里，细脉主虚，小脉主不足，三者相合，说明病位在里而正气虚衰。原文'沉主里，细主虚，小主不足'直接点明，且夏月暴冷伤中、泄痢耗液致正虚，故脉沉细小数主里虚。"}], "n": {"主里虚": 1}, "a": {"21576": "主里虚"}, "t": 1, "np": 0}, "c:滑+沉+濡+平": {"o": "沉濡滑为冬肾当令之平脉，总主肾水得胃气之和，为无病之常。其脉以沉应冬令与肾位，濡滑为胃气与肾水相合，故为平脉。若反见他脉，则示他脏乘肾，依五行生克分五邪：肺乘肾为虚邪，肝乘肾为实邪，脾乘肾为贼邪，心乘肾为微邪。平脉示常，诸邪脉示变，常变之间以胃气存亡与生克顺逆为辨，顺者病轻，逆者病重。", "c": [], "n": {}, "a": {"21670": "__np"}, "t": 1, "np": 1}, "c:弦+微+涩+弱": {"o": "微弱弦涩脉总起来主血虚，并涉及肝脾亏虚。其脉象特征为脉力微弱、脉形弦细而往来涩滞，反映血少脉道不充、血行不畅。原文以“女人血虚者……脉息则微弱弦涩”立论，指出该脉是血虚之候的典型表现，并伴经期不准、色淡量少、行后腹痛喜按、困惫腰膝如折等症。分析进一步认为，微弱弦涩为肝脾亏虚之象：肝藏血、脾生血，亏虚则血少而脉道不充，故脉微弱；气机不畅、血行滞涩，故兼弦涩。两类病机相互关联，血虚为直接脉象所主，肝脾亏虚为血虚之根本，临证当察脏气、审阴阳，参合形证脉色辨治。", "c": [{"name": "主血虚", "desc": "原文明确指出“女人血虚者……脉息则微弱弦涩”，微弱弦涩为血少脉道不充之象。血虚则脉道空虚，故脉微弱；血少而脉行不畅，故兼弦涩。此段以微弱弦涩作为血虚之候的典型脉象，并伴色淡、经少、过期不至等症。"}], "n": {"主血虚": 1}, "a": {"23750": "主血虚"}, "t": 1, "np": 0}, "c:弦+细+小": {"o": "细小弦脉总起来主阴血亏虚、肝郁风动，并常兼夹邪恋、湿热痰滞及疟邪等。其脉象要素中，细小主阴血不足、营卫两虚、正气亏弱；弦主肝郁、风木、邪郁、疟与痛。诸段所涉病机虽异，多围绕正虚与邪郁两端：或阴亏而肝气横逆、风木乘土；或正虚而暑湿热余邪羁留三阴；或阴亏而湿热痰滞互阻中焦；或疟邪深伏三阴、虚实夹杂。各类之间，阴血亏虚为本，肝郁风动为常见标象，正虚邪恋、湿热痰滞、疟邪三阴则为虚中夹实之变。故临床见细小弦脉，当以扶正顾阴为主，兼察肝郁、风动、痰湿、疟邪之有无，虚实兼顾。", "c": [{"name": "主阴血亏虚", "desc": "细小脉为阴血不足、营卫两虚之象。原文多称细小主阴亏、营血不足、气血两亏，如胎动案脉细小而弦，判为营血不足、胎气不固；痱中案细小带弦，谓肾阴亏虚；四诊案细小主气血两亏。故细小弦脉首主阴血亏虚、正气不足之病机。"}, {"name": "主肝郁风动", "desc": "弦脉主肝郁、肝风、气机横逆。原文见左三部细小带弦，谓肝气横逆于中；风木乘土案弦为风木亢盛；痱中案弦为肝风内动；风火痰案弦主肝经风火痰留滞。故弦细并见，主肝郁气滞、风木内动、肝气犯脾之病机。"}, {"name": "主正虚邪恋", "desc": "细小为正虚，弦为邪郁。原文见脉形细小之中带隐弦，谓暑湿热余邪尚羁三阴、无力以消；沉小弦细总述谓邪郁于里、正气不足、营虚邪陷。故细小弦脉主正虚邪恋、余邪未清、邪郁三阴之病机。"}, {"name": "主湿热痰滞", "desc": "细小弦兼涩濡，主阴亏而湿热痰滞互阻。原文见左三部细小带弦，右寸涩、关濡，舌苔薄腻而黄，胸痞呕恶、便结溲赤，谓少阴本亏，湿热挟痰滞互阻中焦，肝气横逆。故细小弦脉可主正虚而湿热痰滞互结、中焦气机壅滞之病机。"}, {"name": "主疟邪三阴", "desc": "弦主疟、主邪郁，细小主阴血不足。原文痎疟案左脉细小而带隐弦，右部弦急而滑，谓痎疟生于三阴，少阴虚、太阴实、厥阴虚实各半，寒热往来、胁痛。故细小弦脉主疟邪羁留三阴、虚实夹杂之病机。"}], "n": {"主阴血亏虚": 2, "主肝郁风动": 3, "主正虚邪恋": 1, "主湿热痰滞": 1, "主疟邪三阴": 1}, "a": {"383": "主湿热痰滞", "471": "主阴血亏虚", "781": "主阴血亏虚", "1196": "主肝郁风动", "5795": "主肝郁风动", "9011": "主正虚邪恋", "9019": "主疟邪三阴", "10648": "主肝郁风动"}, "t": 8, "np": 0}, "c:数+弦+急": {"o": "弦数急脉总起来主邪热内盛、木火亢盛之实，并可见于湿热、肝火、暑风、木火刑金及脱营等证。弦主痛、主风动、主肝木，数主热、主火，急主气逆势迫，三者相合，反映邪热内炽、木火亢盛、气逆不通之病机。其类别之间，湿热阻络、肝火内炽、暑风外袭、木火刑金均属实证热证，而脱营则因实热久羁，伤及气血，转为虚实夹杂。诸类皆以弦数急为共同脉象，但兼症不同，病机各有侧重，总以热盛、火动、气逆为关键。", "c": [{"name": "主湿热", "desc": "弦数急脉可主湿热内蕴。如段，脉弦数急，弦主痛、主络脉拘急，数主湿热，症见舌黄便干胃钝，为湿热阻遏阳明之络，故脉象反映湿热阻腑、络脉不通之机。"}, {"name": "主肝火", "desc": "弦数急脉主肝火内炽。如段，脉数左关弦急，数主火，弦急为肝火亢盛之象，症见失血后咳嗽梦遗，乃肝火在里，上犯肺金则咳，下泄肾气则遗。"}, {"name": "主暑风", "desc": "弦数急脉主暑风外袭、邪热内炽。如段，脉弦急数，弦主风动，急数主热盛，结合季夏发病、壮热头痛呕吐，显系暑风外袭，暑为阳邪，风性急迫，故脉弦急而数。"}, {"name": "主木火刑金", "desc": "弦数急脉主肝火上逆、木侮肺金。如段，左右脉来弦数而急，弦属肝木，数为火象，急则气逆之势，金虚不能平木，肝火上逆，木来乘金，故鼻洪复发而兼咳嗽。"}, {"name": "主脱营", "desc": "弦数急脉主脱营之症，气血大亏而肝脾病。如段，脉数弦急，合色萎肉削、气怯言微、右乳肿痛，为脱营之症，肿痛质热色红，颇有内溃之情，气血大亏，肝脾更病。"}], "n": {"主湿热": 1, "主肝火": 1, "主暑风": 1, "主木火刑金": 1, "主脱营": 1}, "a": {"3259": "主湿热", "4719": "主脱营", "5866": "主肝火", "15376": "主暑风", "15490": "主木火刑金"}, "t": 5, "np": 0}, "pc:左+数+弦+虚": {"o": "左数弦虚脉总属虚实夹杂、本虚标实之候。其核心病机为阴血亏虚、虚火内扰，以虚、弦、数三象为纲：虚主营络内伤、阴液不足；弦主肝失所养、气机郁滞；数主虚火内升、热郁肝胆。由此可衍化为三类主要病机：一为阴虚火旺，阴亏为本、火旺为标，见于劳怯失血诸案；二为肝郁化火，肝气怫郁、火升铄阴，进而冲肺侮脾，形成肝强脾弱之连锁；三为虚中夹实，或暑热壅肺、或阳明腑实，脉象兼滑兼洪，示标热鸱张。诸类之间，阴虚与火旺互为因果，肝郁与脾肺虚弱相互波及，虚损为根、郁热为标，故脉虽数弦而必兼虚象，总以阴血亏虚、气火内扰为枢机。", "c": [{"name": "主营络内伤", "desc": "脉虚弦而数，虚主营血亏虚、生源不旺，弦主肝失所养、气阻于络，数主火升铄阴。原文明言“营络内伤、生源不旺”，因失血连发、劳乏伤营，致肝脾统藏失职，络血上行而心跳火升，故脉虚弦数并见。"}, {"name": "主肝郁化火", "desc": "脉弦数而虚，弦为肝气怫郁，数为火郁于内，虚为肝体自伤。原文“弦为肝旺，数为火郁，虚则肝体自伤”，“肝多怫郁”致气散血竭，“弦数为热郁肝胆”，皆示肝郁化火、冲肺侮脾之机。"}, {"name": "主气散血竭", "desc": "脉虚弦而数，兼右软大，虚弦为肝阴亏虚、阳亢不敛，数为虚热，软大为气散不敛。原文见气逆自汗、足冷面红、夜不成眠、音低神惫，断为“气散血竭之虞”，乃肝郁日久、阴血耗竭、气不收敛之危候。"}, {"name": "主暑热壅肺", "desc": "左脉弦数，右寸关滑数上溢，弦数为热郁肝胆，滑数为暑热壅肺、津液凝滞成涎。原文谓“暑热始终在肺，并不传经”，症见耳聋口苦、胸次迷闷、频吐黏沫，脉象示邪在肺经气分，清肃不行。"}, {"name": "主阳明腑实", "desc": "左脉弦数，右脉洪滑，洪滑主阳明腑实热盛，弦数主肝经郁热、阴分不足。原文见右手足不遂、舌謇不语、面赤便秘，断为“阳明腑实之候”，脉症相符，故以通腑泻热、清肝化痰取效。"}], "n": {"主营络内伤": 1, "主肝郁化火": 1, "主气散血竭": 1, "主暑热壅肺": 1, "主阳明腑实": 1}, "a": {"6610": "主营络内伤", "13404": "主气散血竭", "13981": "主暑热壅肺", "14100": "主阳明腑实", "15864": "主肝郁化火"}, "t": 5, "np": 0}, "c:大+洪+空": {"o": "洪大空脉总起来主虚阳浮越、阴血亏耗之假热证。其脉象洪大而中空，浮取无伦，沉取无根，为根本无根之象，非实火亢盛。所主病机主要有三类：一为虚阳浮越，阳气浮散于外而内里虚寒，见身热欲覆、面赤娇红、四肢厥冷；二为津枯液燥，邪热耗伤津液，气分热盛故脉洪，津亏不敛故中空，见神昏、舌淡无苔；三为戴阳证，肾阳为阴邪所迫，阳气上戴，脉空无神。三者皆以“洪大而空”为共同特征，本质均为虚，或阳虚浮越，或阴津亏耗，或阴阳俱损，故不可作实热论治。原文强调“证有真假凭诸脉，脉有真假凭诸舌”，洪大空脉须结合舌象（如黑滑胖润、淡红无苔）辨其真假，总属虚证、假热之候。", "c": [{"name": "主津枯液燥", "desc": "洪大为热盛，中空为津亏不敛。温邪两候不解，邪热耗伤津液，气分热盛故脉洪，津液大伤故中空。原文谓“津枯而液燥”，见神昏如醉、舌淡红无苔、呓语呢喃，皆津亏燥热、神明失养之症。"}, {"name": "主戴阳证", "desc": "夏月纳凉痛饮，肾阳为阴暑所迫，阳气上戴，脉洪大而空、沉按若无，伴壮热憎寒、目赤口燥不饮、苔黑滑。洪大而空非实热，乃根本空虚、虚阳浮越于上，原文断为“戴阳证”，主温阳祛暑。"}], "n": {"主津枯液燥": 2, "主戴阳证": 2}, "a": {"3345": "主戴阳证", "13536": "主津枯液燥", "14593": "主津枯液燥", "15372": "主戴阳证"}, "t": 4, "np": 0}, "c:浮+虚+缓": {"o": "浮虚缓脉总属阳气虚衰、正气不足，以阳虚气弱为核心病机。浮为虚阳外浮或气浮于外，虚为鼓动无力、精血不充，缓为阳气弛缓、气血不足。三类病机相互关联：阳虚为根本，脾阳不足为阳虚之具体脏腑表现，正虚邪恋则为阳虚气弱、久病正溃之危重转归。原文三案均见浮虚缓脉，或伴弦象，皆断为阳虚而非阴虚，治以温阳益气取效。故本脉主虚、主寒、主阳气衰微，虽偶见易饥、梦遗等似阴虚之症，实为阳虚不能温煦运化所致，不可误作阴虚火旺论治。", "c": [{"name": "主阳虚", "desc": "浮虚缓脉主阳气不足、虚阳外浮。浮为阳虚外越，虚为鼓动无力，缓为阳气弛缓。原文见两足时冷、身多恶寒、伤寒过汗亡阳，皆阳虚不能温煦之验；虽易饥善食、梦遗似阴虚，实为阳虚不能运化、虚阳扰动所致。"}, {"name": "主正虚邪恋", "desc": "脉浮缓而虚，浮为气浮于外，缓为湿滞，虚为正气大伤。疟久正溃，元气衰败，故卧床昏睡、气息仅属、粒米不入、舌灰面惨。此正虚为主，余邪未清（午后微热），属正虚邪恋、胃气未绝之危候。"}], "n": {"主阳虚": 2, "主正虚邪恋": 1}, "a": {"3570": "主阳虚", "15220": "主阳虚", "16710": "主正虚邪恋"}, "t": 3, "np": 0}, "c:弦+浮+小": {"o": "浮弦小脉总起来主风木乘土、正虚气滞之病机。浮为表、为风，弦主肝木、主气滞，小主正虚。两案中，飧泄案脉浮弦而小，断为风木乘土、脾虚不运，证见完谷不化、腹痛；中满案脉浮小而弦、按之无力，断为气虚不运、气机壅滞，证见中满朝宽暮急。两类病机相互关联：风木乘土与气虚气滞皆以正虚为本，土虚则木贼，气虚则气滞，故脉象浮弦小而无力。总以正虚为核心，风木、气滞为标，治当补脾抑木、行气消胀。", "c": [{"name": "主风木乘土", "desc": "浮弦为风木之象，小脉示土虚。原文见飧泄案，脉浮弦而小，断为风木乘土，肝木克脾，脾失健运，故完谷不化、腹痛；又中满案浮小而弦，弦主气滞，由脾虚不运、气机壅滞所致。"}], "n": {"主风木乘土": 2}, "a": {"2899": "主风木乘土", "15251": "主风木乘土"}, "t": 2, "np": 0}, "c:数+沉+洪": {"o": "沉洪数脉总属里实热证，以热盛于里为基本病机。沉主病位在里，洪数主热邪炽盛，三者相合，揭示热邪内蕴、气血壅盛之象。所归纳三类病机——主里热、主热结、主风火——相互关联：里热为基本病理，热结为热邪凝聚成结，风火为热盛引动风阳。原文中此脉见于少阳络热误补致风火相扇、马刀痈肿，以及外感衄血之里有热结，均体现邪实热盛、非虚象。故临床见此脉，当辨热之所在与兼夹，总以清里泄热、解毒散结为要。", "c": [{"name": "主里热", "desc": "沉主病位在里，洪数主热盛。原文如“六脉沉洪而数”示里热炽盛、风火相扇；“脉沉洪数，里有热结”明言热结于里。故沉洪数脉总主里热壅盛之病机。"}], "n": {"主里热": 2}, "a": {"5668": "主里热", "24736": "主里热"}, "t": 2, "np": 0}, "pc:右+弦+微+软": {"o": "右·弦微软脉总以虚为本，兼见肝木偏亢与痰湿内滞。右软主气分不足，或脾肾气弱、水湿不运，或气营交困、络脉失养；右微弦则土虚木乘，脾受克伐而运化失职；左微弦主肝郁血少，气郁化痰，痰入筋骨发为流痰。四类病机相互关联：气虚为根，土虚则木乘，肝郁则血少，气弱则痰湿流注，形成虚中挟滞、内因虚损之候。脉象软中带微弦，既示正气亏虚，又示肝木偏亢与痰湿为患，故病程缠绵，不易速效。", "c": [{"name": "主气虚", "desc": "右脉软为气弱之征，原文两段均见右软，一因脾肾气弱、水湿不运而见足肿神疲、胃呆溲少，一因气分不足、气营交困而患处肿木、手臂不能举动，皆以软脉示正气亏虚，故主气虚。"}], "n": {"主气虚": 2}, "a": {"9833": "主气虚", "10036": "主气虚"}, "t": 2, "np": 0}, "c:细+浮+小": {"o": "浮小细脉总起来主外邪未解而气血已伤，或郁火内伏而外显假寒。浮脉主表，小细主气血不足，故浮小细并见，多示正虚邪恋之候。若兼风寒湿痹，则外邪未祛而正已伤；若沉按坚搏，则又为郁火内伏、不得宣越之象。两类病机一为外邪伤正，一为内火郁伏，看似相反，实则均以浮小细为共同脉象，提示临证须结合沉取及兼症，辨其虚实寒热。", "c": [{"name": "主外邪正伤", "desc": "浮主表邪未解，小细主气血不足。如案中素体肥胖，风寒湿三气合而成痹，脉浮小而细，示外邪未祛而正已伤，故宜祛风渗湿、通经活络。"}], "n": {"主外邪正伤": 2}, "a": {"15999": "主外邪正伤", "17362": "主外邪正伤"}, "t": 2, "np": 0}, "pc:左+弦+浮+硬": {"o": "左弦浮硬脉总起来主肝胆火盛、阴虚阳亢、气血两虚及热痰中焦四类病机。弦主肝，硬主火盛，浮主上炎，故首主肝胆之火挟热上冲；浮弦硬而不任重按，又为阴血亏虚、阳气外浮之象；脉弱而浮硬，兼经血不行、身体甚弱，则主气血两虚；右脉沉滑，舌苔黏腻，涎沫上溢，又示热痰杜塞中焦。四类之间相互关联：肝胆火盛可灼伤阴血而致阴虚阳亢，阴虚阳亢又可耗伤气血而致气血两虚，火盛炼液成痰则痰热中阻，痰热又加重火盛上冲。总属本虚标实、虚实夹杂之候，以肝胆火盛、阴虚阳亢为标，气血两虚为本，热痰中焦为兼夹。", "c": [{"name": "主肝胆火盛", "desc": "弦为肝脉，硬主火盛，浮主上炎。左脉弦浮硬，提示肝胆之火挟热上冲。如案一头痛目睑疼、涎沫上溢，案二面浮热、心中发热，皆火性上炎之象。"}], "n": {"主肝胆火盛": 2}, "a": {"19904": "主肝胆火盛", "20383": "主肝胆火盛"}, "t": 2, "np": 0}, "pc:左+弦+微+硬": {"o": "左弦微硬脉总属肝郁气逆、血虚火旺，兼木旺克土、脾胃受戕之候。其脉左部弦而微硬，弦主肝郁，硬为气郁化火伤阴，故主肝经气郁与血虚火盛；右部濡弱或重按无力，为木旺克土、脾胃虚弱之象。三类病机相互关联：肝郁气逆为始动因素，气郁化火伤阴则血虚火旺，木旺乘土则脾虚不运。病本在肝，标在脾胃，肝郁化火伤阴为本，木旺克土致脾胃不运为标。临床可见便血腹痛、饮食减少、身体羸弱、潮热便干等症，总以肝郁阴伤、脾弱木乘为病机核心。", "c": [{"name": "主肝郁气逆", "desc": "左脉弦而微硬，弦为肝脉，硬示气机郁滞、失于柔和。原文见左部弦硬，伴便时腹疼、血下多，为肝气横逆、郁而化火之象；又见右脉近弦，木旺克土，故主肝郁气逆、横逆犯中。"}], "n": {"主肝郁气逆": 2}, "a": {"20463": "主肝郁气逆", "20762": "主肝郁气逆"}, "t": 2, "np": 0}, "pc:左+弦+缓+迟": {"o": "左弦缓迟脉总起来主肝旺、湿滞、脾虚、血虚四类病机。左弦主肝气肝阳上升，右迟缓主湿滞未楚、脾胃运化无权，而‘营血本虚’为发病之本。四者相互关联：营血本虚，肝失濡养，肝阳上亢则脉弦；肝旺乘脾，脾运失健，湿滞内停，则右脉迟缓；湿滞又进一步困阻脾胃，加重脾虚。故其病机以血虚为本，肝旺为标，脾虚湿滞为中间环节，形成本虚标实、虚实夹杂之候。脉象弦缓迟并见，提示痛势虽缓而肝旺脾弱、湿滞未化之兼证仍在，治疗需柔肝泄肝、和胃畅中，兼顾标本。", "c": [{"name": "主肝旺", "desc": "左弦为肝气肝阳上升之征。原文谓‘营血本虚，肝气肝阳上升’，脉左弦，伴头眩心惊，说明肝阳上扰、肝气不舒。弦脉应肝，左关候肝，故左弦主肝旺，为病机之要。"}], "n": {"主肝旺": 1}, "a": {"391": "主肝旺"}, "t": 1, "np": 0}, "c:细+微+小": {"o": "微细小脉总起来主阳气衰微、气血不足与阴伤火郁、气机壅滞两类病机。微者阳微，细者阴弱，小者气少，三象并见，首先反映正气亏虚：或为胃阳大衰、中焦虚寒，治当温理中阳；或为阴液不足、气血两亏。若兼数象，则于阴亏之中更见郁火内郁、气机壅滞，形成阴伤为本、火郁气壅为标的虚实夹杂之候。可见此脉以虚为本，虚中可夹郁火、气壅之标，虚有阳衰、中虚、阴伤之异，实有火郁、气壅之别，临证当结合兼脉与症候分辨主次。", "c": [{"name": "主阳衰", "desc": "脉微细小并见，微为阳气衰微，小为气少，细为阴弱，三象合参，示阳气大衰、气血不足。原文以“脉微细小”断“胃阳大衰”，并治以理中兼摄其下，说明中阳衰而元气不固，故主阳气衰微、中焦虚寒之病机。"}], "n": {"主阳衰": 1}, "a": {"1212": "主阳衰"}, "t": 1, "np": 0}, "c:细+促+坚": {"o": "促细坚脉总属正虚邪结、阴阳不相顺接之候。细主阴亏，坚主邪伏深入，促主阳结，三者相合，反映正虚于内而邪结于里，尤以阴亏阳结、邪伏厥阴为核心。原文‘平素积劳致虚，邪伏厥阴’点明虚与邪并存；‘神气索然、腹中动气、舌红嗌干、寒热日迟’为阴亏阳结、正虚邪伏之外候。因温清难用，故以复脉汤存阴勿涸，希图援救。三类病机相互关联：正虚是基础，阴亏阳结是病性，邪伏厥阴是病位，共同构成促细坚脉的复杂病机格局。", "c": [{"name": "主正虚邪结", "desc": "脉促细坚，细为阴亏，坚为邪伏深入，促为阳结，三者并见，示正虚而邪气结聚，阴阳不相顺接。原文‘平素积劳致虚。邪伏厥阴’及‘神气索然’正是正虚邪结之象。"}], "n": {"主正虚邪结": 1}, "a": {"1493": "主正虚邪结"}, "t": 1, "np": 0}, "pc:六+数+洪+紧": {"o": "六·数洪紧脉总起来主热盛邪实、表里俱病。洪数主热盛，紧主邪实壅结，三者相合，提示热邪亢盛而里有实结，且表里同病。原文虽通体似火证，但脐痛拒按、断为'阳中之阴'，说明热象虽盛而里有实滞，非纯热无滞。苦热芳香一剂热退，正针对洪数热盛与紧实壅结。三类病机相互关联：热盛为根本，邪实壅结为关键，表里俱病为范围，共同构成洪数紧脉的完整病机图景。", "c": [{"name": "主热盛", "desc": "洪数脉象直接反映热邪亢盛。原文'六脉洪数而紧'伴面赤身热、舌黄燥渴、便闭溺短，通体似火证，洪数为热盛之典型表现，说明热邪充斥表里，故主热盛。"}], "n": {"主热盛": 1}, "a": {"5639": "主热盛"}, "t": 1, "np": 0}, "pc:关+数+弦+急": {"o": "关·数弦急脉总主肝火内炽，兼及火邪上下交攻之病机。数主火，弦急为肝火亢盛之象，左关候肝，故脉见数弦急，首责肝火。肝火在里，上犯肺金则咳嗽，下泄肾气则梦遗，形成火刑肺金与火泄肾气两类子病机。失血后阴血已伤，火旺更灼，久延势必成劳，故又主劳损之渐。四类中，主肝火为根本，其余三类皆由肝火亢盛派生：上炎刑肺、下迫泄肾、耗阴成劳。总括而言，此脉以肝火为核心，揭示火邪上下交攻、由实致虚的病变趋势。", "c": [{"name": "主肝火", "desc": "脉数左关弦急，数主火，弦急为肝火亢盛之象。失血后咳嗽梦遗，乃肝火在里，上犯肺金则咳，下泄肾气则遗。脉数弦急正是肝火内炽之征，故主肝火。"}], "n": {"主肝火": 1}, "a": {"5866": "主肝火"}, "t": 1, "np": 0}, "pc:右+弦+细+紧": {"o": "右·弦细紧脉总起来主肝木郁结、营血亏虚、火动神怯之复合病机。弦紧主木郁气滞，细主营液内耗，关浮大主虚阳上扰、木火引动君火，寸濡则心营不足。诸类相互关联：肝郁日久化火，火动则耗伤营液，营虚则木失滋养而郁结更甚；营血亏少则胆气不足，神怯不安。原文症见烦扰不安、夜不得眠、胆虚而怯，纯属虚证而兼郁火，故其脉象总以虚为本、郁火为标，虚、郁、火三者互为因果。", "c": [{"name": "主木郁", "desc": "弦脉为肝木之象，紧细相合，提示肝气郁结不达。原文谓“木郁不达”，右脉紧细而弦，正合肝郁气滞、疏泄失常之机，故以弦紧细主木郁气结。"}], "n": {"主木郁": 1}, "a": {"6567": "主木郁"}, "t": 1, "np": 0}, "pc:右+弦+滑+和": {"o": "右·弦滑和脉总起来主气郁、痰湿及肝胃不和。弦主气机郁滞，滑主痰湿内蕴，右关候脾胃，故弦滑并见右关，反映肝气郁结、痰湿中阻、肝胃失和之病机。原文脉象稍柔和，是郁滞稍解、痰湿渐化之征，症见胀满渐舒、略能安谷，说明脉象好转与症候相应。三类病机相互关联：气郁可生痰湿，痰湿可碍气机，二者共同导致肝胃不和；治疗从肝胃调和，使气畅湿化，则脉转柔和。", "c": [{"name": "主气郁", "desc": "弦脉为气机郁滞之象。原文左寸关弦象稍退，说明肝气郁结渐解；右关弦滑亦稍柔和，表明中焦气郁亦得舒缓。弦主气郁，故脉弦主气机不畅，郁滞于肝胃。"}], "n": {"主气郁": 1}, "a": {"7866": "主气郁"}, "t": 1, "np": 0}, "c:大+弱+缓": {"o": "弱缓大脉总主气虚挟痰。左脉弱缓大，弱为气衰，缓大为气虚无力鼓动，故主气虚；右关带滑，滑为痰湿内蕴，故主痰湿。二者相合，反映脾虚气弱、运化失职、湿聚成痰之病机。原文以“气虚挟痰”概括，并谓“脉症相符”。气虚为本，痰湿为标，脾虚生湿生痰，痰阻中枢，进而影响升降，变生诸症。故弱缓大脉所主病机以气虚为核心，痰湿为兼，脾虚为根源，三者相互关联，不可截然分割。", "c": [{"name": "主气虚", "desc": "左脉弱缓大，弱为气不足，缓大为气虚无力鼓动。原文谓“左弱缓大为气虚”，又言“气瘠于内”“气弱则脾土少运”，故弱缓大脉主气虚，尤以脾肺气虚为主。"}], "n": {"主气虚": 1}, "a": {"7967": "主气虚"}, "t": 1, "np": 0}, "c:大+软+短": {"o": "大软短脉总起来主湿郁、中虚、痰郁及筋伤四类病机。其脉来甚慢即迟缓，为湿浊困阻、阳气不运之征；中虚则运化失职，痰湿内生，郁阻脉道；湿热不攘，伤及筋脉，则见大筋软短、小筋弛长。四类病机相互关联：中虚为根本，湿郁痰郁为标象，筋伤为湿热痰郁久羁之变。脉象软短迟缓，既反映正气不足，又提示湿痰郁滞，故临床当标本兼顾，以健脾化湿、涤痰通络为要。", "c": [{"name": "主湿郁", "desc": "脉来甚慢即迟缓，为湿浊困阻、阳气不运之象。原文“湿热不攘”明言湿邪郁遏，脉迟缓正合湿郁气机不畅之机，故大软短脉主湿郁为患。"}], "n": {"主湿郁": 1}, "a": {"12361": "主湿郁"}, "t": 1, "np": 0}, "pc:左+数+沉+小": {"o": "左·数沉小脉总起来主阴血不足、虚热内扰，兼见气虚与疟邪未净。其脉沉小为阴血亏虚，数为虚热内动；右脉浮濡无力近数，为脾肺气虚；脾部弦洪，为疟邪未净。诸类之间，以阴虚内热为核心，气虚为兼，疟邪为标，正虚邪恋为转归。年逾六十形弱，劳心劳力，疟后见此脉，示虚实夹杂：阴血不足为本，虚热为标，气虚为兼，疟邪未净为标。疟去后脉转缓弱，示邪退正虚，故总以正虚为主，虚中夹实。", "c": [{"name": "主阴虚内热", "desc": "左脉沉小而数，沉主里、小主阴血不足，数主热，合示阴血亏虚、虚热内扰。原文年逾六十形弱，疟后见此脉，正是阴血不足、虚热内生之象。"}], "n": {"主阴虚内热": 1}, "a": {"15100": "主阴虚内热"}, "t": 1, "np": 0}, "c:细+紧+疾": {"o": "细紧疾脉总属阳虚寒盛、邪正相争之候。细主阳虚，紧主寒邪，疾主邪正相争，三者相合，多见于素体虚弱、寒邪内侵、厥阴受病之证，如原文之寒战发热、胁痛牵引、干呕胸胀。若失治或误汗，则阳气外越，脉可变数大无伦、重取近散，转为汗多亡阳之危候。故本脉所主，以阳虚寒盛为本，邪正相争为标，甚则阳气外脱，各病机之间由实转虚、由寒化脱，层层递进。", "c": [{"name": "主阳虚寒盛", "desc": "脉细为阳虚，紧为寒，原文谓“细为阳虚，紧为寒”，且患者平素虚弱，寒战发热，胁痛牵引，干呕胸胀，显系阳虚寒盛，厥阴受邪，故以温经散寒主治。"}], "n": {"主阳虚寒盛": 1}, "a": {"16106": "主阳虚寒盛"}, "t": 1, "np": 0}, "c:浮+洪+促": {"o": "浮洪促脉总起来主热盛，包括外感温邪内炽和少阳枢机不利化热。浮洪为热盛于外，促为热迫急数，故脉浮洪促主要反映热邪炽盛、病势急迫。从原文看，初诊脉弦数主少阳枢机不利，热郁少阳；后脉转浮洪而促，伴大热大渴、舌鲜红，示温邪内炽，热盛于外。两类均属热证，但前者偏少阳郁热，后者偏温邪炽盛，病情由郁转盛，热势鸱张。故浮洪促脉所主病机以热盛为核心，涉及少阳枢机不利和温邪内炽，总属热邪为患，病位由少阳转气分，热势由郁而炽。", "c": [{"name": "主热盛", "desc": "浮洪为热盛于外，脉转浮洪而促，伴陡然大热大渴微汗头晕痛，舌鲜红，示温邪内炽，热势鸱张，故浮洪促脉主热邪炽盛。"}], "n": {"主热盛": 1}, "a": {"16720": "主热盛"}, "t": 1, "np": 0}, "pc:六+大+缓+软": {"o": "六脉缓大而软，总属脾虚湿盛之候。缓大非实，软示不足，故非邪实，乃正虚。脾主运化，脾虚则水湿不化，湿盛则肢体肿重、腹胀泄泻。脉象缓大而软，既反映脾虚不运，又提示湿邪内停。二者互为因果：脾虚生湿，湿盛困脾。治疗先止泻以治标，后补中以治本，佐以利湿，终获痊愈。故此类脉所主病机以脾虚为本，湿盛为标，虚实夹杂，总以健脾祛湿为要。", "c": [{"name": "主脾虚", "desc": "脉缓大而软，缓大非实，软示不足。原文谓“皆缘以泄伤脾”，妊娠泄泻伤脾，脾虚不运，故脉象缓大而软。治以参、术、茯苓等补脾而愈，说明此脉主脾虚。"}], "n": {"主脾虚": 1}, "a": {"17326": "主脾虚"}, "t": 1, "np": 0}, "pc:左+弦+涩+弱": {"o": "左弦涩弱脉总起来主肝血郁滞、肺气不足、气机失司及本虚标实之证。左脉弦涩，为肝血郁滞，血行不畅；右脉弱，为肺气不足，宣发无力。肺主出气，肾主纳气，气虚则阳不下达，金不制木，木反乘金，故见咳嗽、浮肿先于身半以上，继以失血。弦涩弱并见，反映本虚标实、气机升降失司，病位涉及肝、肺、肾，以虚为本，以郁滞为标。治宜滋肝益肾、纳气归元，不可徒作相火论治。诸类之间相互关联：肝血郁滞可影响肺气宣降，肺气不足又可致金不制木，而气机失司贯穿始终，本虚标实为总病机特点。", "c": [{"name": "主肝血郁滞", "desc": "左脉弦涩，弦主肝郁，涩主血滞，故左弦涩为肝血郁滞之象。原文指出‘左弦涩为肝血郁滞’，并见失血，说明肝血不畅，郁滞于内，血行受阻，甚则血不循经而外溢。"}], "n": {"主肝血郁滞": 1}, "a": {"18484": "主肝血郁滞"}, "t": 1, "np": 0}, "pc:左+弦+细+硬": {"o": "左弦细硬脉总起来主肝血虚、津液短少，并常与右脉濡沉同见而构成气血两亏兼停饮之证。其脉弦为肝病之象，细为血少，硬为津液不濡，故核心病机在阴血亏虚、津液短涩。然单见左脉尚不足以概全，需合右脉及症候，方知兼有湿痰留饮、中焦气化不足。三者关系：肝血虚与津液短互为因果，血虚则津少，津少则脉硬；气血两亏为整体背景，停饮为兼夹之邪。此脉所主，以虚为本，以饮为标，虚实夹杂，故咳喘夜不能卧。", "c": [{"name": "主肝血虚", "desc": "左脉弦细而硬，弦为肝脉，细为血少，硬为津液短涩，故主肝血不足、津液亏短。原文明言“左脉弦细而硬，为肝血虚、津液短”，且患者久咳喘促，夜不能卧，阴血耗伤，脉道失濡，故见此象。"}], "n": {"主肝血虚": 1}, "a": {"20402": "主肝血虚"}, "t": 1, "np": 0}, "pc:右+弦+沉+硬": {"o": "右弦沉硬脉总属肝脾同病、虚实夹杂之候。其核心病机为肝郁血虚火旺、脾胃虚弱而木乘土位，并伴气机遏抑。弦硬沉主肝之实（火盛、气郁）与虚（血虚），弦而无力主脾土受戕。三者相互关联：肝血虚火盛则肝气郁结，木郁则横逆犯土，脾胃失运则土虚更受木乘，气机因之遏抑不舒。故本脉所主以肝脾不调为枢，虚（血虚、脾虚）、实（火盛、气郁、木乘）并见，治当遵“厥阴不治，求之阳明”，健补脾胃以运中焦，佐理肝木。", "c": [{"name": "主肝郁血虚火旺", "desc": "原文左脉弦硬而沉，弦主肝病，硬为火象，沉为郁结，合示肝经血虚火盛而肝气郁结。血虚则脉失濡养，火盛则脉道拘急，气郁则脉气不舒，故见弦硬沉之象。"}], "n": {"主肝郁血虚火旺": 1}, "a": {"20514": "主肝郁血虚火旺"}, "t": 1, "np": 0}, "pc:六+沉+涩+长": {"o": "沉涩长脉总属阴中兼阳之象。沉为阴脉，主里、主阴；涩为阴脉，主滞、主血少；长为阳脉，主气盛。三者相合，反映病机以阴寒内凝、气机郁滞为基础，兼有阳气不伸或气血不畅。原文以浮沉长短滑涩分阴阳，并谓沉涩短为阴、浮滑长为阳，沉涩长即一阴二阳之属，说明其病机非纯阴纯阳，而是阴阳相兼、虚实错杂。所主病机可归纳为阴证、阴阳相兼、气机郁滞三类：阴证言其属性，阴阳相兼言其构成，气机郁滞言其具体病理。三者相互关联，阴寒内盛则气机凝滞，气滞血涩则阴阳不相顺接，故临床可见于里虚寒证兼气滞血瘀之候。", "c": [{"name": "主阴证", "desc": "原文以沉、涩、短为阴脉，沉涩相兼属阴，主阴证。阴邪内盛或阳气不足，脉气不能鼓动于外，故见沉涩；长脉虽兼，然沉涩为主，仍属阴类，反映病机偏于阴寒内凝。"}], "n": {"主阴证": 1}, "a": {"21810": "主阴证"}, "t": 1, "np": 0}, "c:滑+紧+缓": {"o": "缓滑紧脉在产后发热的辨证中，主要用以鉴别火证与表寒。其脉象特征为缓滑而不紧，表明内无寒邪紧束，而是火热内盛、气血壅盛。原文指出“凡属太过，皆能生火”，火盛于内则见潮热、烦渴喜冷、便实尿赤等症，脉缓滑正是里热壅盛之征，而非表寒之象。因此，该脉所主病机为火热内盛，治宜清化饮类清之。此脉象在产后发热中具有重要的鉴别诊断意义，提示医者当从火论治，而非解表散寒。", "c": [{"name": "主火热内盛", "desc": "脉缓滑不紧，说明内无寒邪紧束，而火热蒸腾、气血壅盛。原文强调“凡属太过，皆能生火”，火盛于内则潮热烦渴、便实尿赤，脉缓滑正是里热壅盛而非表寒之征，故断为火证。"}], "n": {"主火热内盛": 1}, "a": {"23784": "主火热内盛"}, "t": 1, "np": 0}, "c:弱+紧+缓": {"o": "紧缓弱脉在此段中并非单一脉象，而是弦急、不甚紧、时缓弱并见，总起来主肝经风火夹脾虚之本虚标实证。弦急主肝火亢盛、风热上攻，为标实；缓弱主脾虚不运、正气困乏，为本虚；不甚紧则示风火之势不专，虚象已显。三类病机相互关联：肝火风热上扰致耳根肿痛脓血，脾虚气弱致食少体困，二者合成本虚标实之局。故临证须脉证合参，既清肝疏风，又健脾扶正，不可偏执一端。", "c": [{"name": "主肝火风热", "desc": "脉见弦急，为肝火亢盛、风热上攻之象。原文述耳根连颈项头角肿痛、脓血迭出，皆风火循经上扰所致，故弦急脉主肝经实火与风热。"}], "n": {"主肝火风热": 1}, "a": {"24001": "主肝火风热"}, "t": 1, "np": 0}, "c:大+涩": {"o": "涩大脉总起来主病机以血虚液亏、气滞血瘀为基础，兼涉热盛瘀滞、寒凝气滞、胃逆血耗及虚实夹杂等多类。涩主血少、气滞、瘀阻，大主邪实、气浮或虚阳外越，二者并见，既可因阴血亏虚、脉道不充而见血虚液亏，也可因气血壅塞、瘀热互结而见气滞血瘀或热盛瘀滞；寒邪内盛、血凝脉阻则见盛大以涩之寒中；木火犯胃、营血内耗则见右涩大之胃逆血耗。此外，涩大脉常与滑、芤、虚等象兼见，反映上盛下虚、瘀血内壅、暑伤气津等虚实夹杂之候。诸类之间，血虚与瘀滞互为因果，寒热虚实可相互转化，临证当结合部位、兼脉及症候，辨其标本主次。", "c": [{"name": "主血虚液亏", "desc": "涩主血少脉道不充，大主阴血亏而气浮。原文如“诊脉涩且大，左手尤涩，涩属血虚，当益血分”，左脉候血，左手尤涩更印证血分不足；又如“脉涩左大，涩主液亏血少”，食入为噎，为液亏气滞，胃失濡润。故涩大脉可主血虚液亏之证。"}, {"name": "主气滞血瘀", "desc": "涩主气滞血瘀、脉道不利，大示邪实或气血壅塞。原文如“脉涩寸口大”，涩主血瘀气滞，寸口大主阳浮气逆，见经来腹中胀闷而痛；又如大小涩脉总述“气滞血瘀，涩示脉道不利，大小不一示气血壅塞”，故涩大脉主气滞血瘀、经行不畅、痛证等。"}, {"name": "主热盛瘀滞", "desc": "洪大主热盛气浮，涩主血行不畅、瘀滞。原文如“膈痛脉洪大而涩，先用清热行血之品痛止”，是热邪内蕴，灼血成瘀，瘀热互结，气血不通。故涩大脉可主热盛瘀滞、瘀热互结之实证，治当清热行血。"}, {"name": "主寒凝气滞", "desc": "大示邪气亢盛，坚示寒邪凝滞收引，涩示气滞血瘀。原文论“阴盛生内寒，寒气积胸中不泻则温气去、血凝泣、脉不通，故脉盛大以涩，名曰寒中”，盛大示寒邪壅盛，涩示血凝脉不通。故涩大脉可主寒凝气滞、血凝脉阻之寒中证。"}, {"name": "主胃逆血耗", "desc": "右涩大，右主胃，涩为营血内耗、脉道不充，大为木火升腾、胃逆不降。原文如“脉右涩大，胃逆不降”，因劳怒触动情志，少阳木火盛于寅，犯逆阳明上凭诸窍，致呕逆、耳鸣咽痹、食纳久留脘中，营血耗无以养心。故涩大脉主胃逆不降兼营血内耗。"}], "n": {"主血虚液亏": 2, "主气滞血瘀": 1, "主热盛瘀滞": 1, "主寒凝气滞": 1, "主胃逆血耗": 2}, "a": {"1187": "主血虚液亏", "1393": "主胃逆血耗", "4419": "主胃逆血耗", "7192": "主血虚液亏", "17124": "主气滞血瘀", "25189": "主寒凝气滞", "25190": "主热盛瘀滞"}, "t": 7, "np": 0}, "pc:右+沉+小": {"o": "右·沉小脉总以正虚为本，尤以脾胃气虚、中气不足为核心。沉主里、小主虚，右脉候脾肺，故凡右沉小者，多示脾阳不振、运化失职，或胃土久伤、中气大虚。在此基础上，常兼见他部脉象而现兼夹之机：兼左虚大或左关虚弦者，为肝木乘土、肝气内变；兼弦大者，为阳明积热内恋而木来乘土；兼濡涩者，为气虚痰郁、肺失治节；兼左洪大浮者，为正虚邪恋、邪陷厥阴。诸类之间，脾虚气滞与中气大虚同属正虚，一为气机郁滞，一为气虚乏力；肝木乘土由脾虚而肝乘，属虚实夹杂；正虚邪恋为虚中夹实，多见于温病后期；气虚痰郁为虚而兼痰。总归右沉小脉以虚为本，或纯虚，或虚中夹实，治当扶正为主，忌攻伐消导。", "c": [{"name": "主脾虚气滞", "desc": "右脉沉小，右主脾肺，沉小示脾阳不振、气机郁滞。如原文'脾不醒则胃络不舒，脉右沉小'，脾失健运则胃络气阻，故右胁疼刺不舒；又'脉沉右小，左虚大，脐上有动气，䐜胀不嗜食'，右小为脾胃气虚，中虚不运则胀而不嗜食。"}, {"name": "主中气大虚", "desc": "右脉沉小乏力，沉主里、小主虚，乏力为气弱，反映阳明胃土久伤、中气不足。如呕吐案'右脉沉小乏力，左关虚弦'，胃虚失降、肝气上逆，汤药入口即呕；又'中气大虚，肝气内变'，右小为脾胃气虚，忌用攻伐消导。"}, {"name": "主正虚邪恋", "desc": "右脉沉小示气分邪减而正已伤，如'右脉稍沉而小，左脉仍洪大而浮'，右小示气分邪减，左洪大示血分伏邪仍盛，更见神识昏、瘛疭、肢厥，邪陷心包，正虚邪恋，故断为非吉兆。"}, {"name": "主肝木乘土", "desc": "右脉沉小兼弦大，沉小为脾虚，弦大为肝气偏旺、阳明积热，木来乘土。如'右脉弦大，舌黄，晡热，是阳明积热内恋，而木来乘土'，下痢色紫后重；又'左关虚弦'，肝木乘土犯胃而呕吐。"}, {"name": "主气虚痰郁", "desc": "右脉濡涩，濡为气虚，涩为痰郁，肺为娇脏，不耐邪侵。如'左脉沉小，右脉濡涩'，肝阴不足，气虚痰郁，肺虚治节不行，则鼻不闻香臭、冒风咳甚、卧时喉中水鸡声，脉沉小濡涩正合肝虚肺郁、气虚痰郁之机。"}], "n": {"主脾虚气滞": 1, "主中气大虚": 1, "主正虚邪恋": 1, "主肝木乘土": 3, "主气虚痰郁": 1}, "a": {"5036": "主中气大虚", "5165": "主正虚邪恋", "12456": "主气虚痰郁", "13568": "主肝木乘土", "14658": "主肝木乘土", "15959": "主脾虚气滞", "15976": "主肝木乘土"}, "t": 7, "np": 0}, "pc:尺+滑+动": {"o": "尺部滑动脉总起来主痰积、湿热、肝气郁结，并常兼见本虚标实之候。滑脉主痰，动主痛，右关滑动多提示痰积中焦；若兼数则湿热内蕴；左关弦搏则肝木气旺，气结入络可成梗块。然原文又见尺寸脉微缓，泄痢日久，气血两亏，说明滑动脉所主之痰积湿热肝气，多建立在元气已虚的基础上，形成本虚标实、攻补两难的复杂病机。四类病机相互关联：痰积与湿热常相合为患，肝气郁结可促生痰湿，而正虚又使痰湿热胶结难化，故临床须权衡虚实，择性味不猛者通化。", "c": [{"name": "主痰积", "desc": "原文多次言“右关滑动……是痰积在中焦”，滑脉主痰，动主痛，右关候脾胃，滑动并见则痰积中焦，舌苔黄白而腻亦为痰湿之征。"}, {"name": "主本虚标实", "desc": "原文“尺寸脉俱微缓，泄痢一载，气血两亏”，微缓主正虚，滑动主痰积湿热，脉象反映本虚标实，痰热郁结而元气已弱，故攻补两难。"}], "n": {"主痰积": 1, "主本虚标实": 3}, "a": {"10858": "主本虚标实", "13270": "主痰积", "13666": "主本虚标实", "14781": "主本虚标实"}, "t": 4, "np": 0}, "pc:右+濡+迟": {"o": "右濡迟脉总主阳气衰微、寒湿内阻之病机。濡为气虚湿滞，迟为阳不胜阴，故其核心在于阳气不足、阴寒内盛。具体可分四类：一主阳虚，命火式微，阳陷入阴；二主寒湿，太阴少阴寒湿困阻，气化不行；三主气虚湿滞，中土受戕，清气不升；四主脾肾阳衰，八脉无气，阴寒内盛。四类相互关联：阳虚为根本，寒湿为标象，气虚湿滞为中间环节，脾肾阳衰为脏腑定位。右脉候脾，左脉候肾，右濡迟多责脾阳不运，左濡迟多责肾阳不振，总不离阳气虚衰、阴寒内盛之机。", "c": [{"name": "主阳虚", "desc": "濡迟脉主阳气式微，命火不足。原文言“右脉濡迟，阳陷入阴，命火式微”，左迟右濡示“肝阴久亏、阳气不振”，左脉濡迟属“少阴寒湿，肾阳不振”。迟为阳不胜阴，濡为气虚，故主脾肾阳虚、命门火衰。"}, {"name": "主寒湿", "desc": "濡迟脉主寒湿内阻。原文明言“阴寒小便不利之脉，脉必濡缓，甚则濡迟”，右脉濡迟属“太阴寒湿”，左脉濡迟属“少阴寒湿”。濡主湿，迟主寒，寒湿困阻，气化不行，故见小便不利、腹痛足缓等症。"}, {"name": "主脾肾阳衰", "desc": "濡迟脉主脾肾阳气衰微、中气下陷。原文“阳陷入阴，命火式微”，“肝肾内衰、八脉无气”，分属太阴、少阴寒湿。右脉濡迟责之脾阳不运，左脉濡迟责之肾阳不振，合而主脾肾阳衰、阴寒内盛之机。"}], "n": {"主阳虚": 1, "主寒湿": 1, "主脾肾阳衰": 1}, "a": {"269": "主脾肾阳衰", "2186": "主阳虚", "25093": "主寒湿"}, "t": 3, "np": 0}, "pc:两+细+沉": {"o": "两·细沉脉总属里虚之候，以沉候病位在里，细候气血阴精不足。其主病机可归为四类：一主肾虚，见两尺沉细，为肾阴或肾阳精血亏虚；二主脾虚寒湿，见两关沉细，为中阳不振、寒湿食积内阻；三主肝火犯肺，以左关弦数、右寸弦大滑兼两尺沉细，示肝火亢盛、上刑肺金；四主冲任失司，因肾阴亏虚、精血不足而经血不调。四类之中，肾虚为本，脾虚寒湿为在中焦，肝火犯肺为木火偏亢、上逆侮金，冲任失司为肾虚波及奇经。数细沉脉另属邪陷正虚、热闭阴伤，可视为细沉脉兼数之变证，总以正虚为本、邪郁为标。", "c": [{"name": "主肾虚", "desc": "两尺沉细，尺候肾，沉为在里，细为阴血不足。原文见两尺沉细，伴腰腿疼、居经不行，断为肾阴亏虚或肾阳不足、精血亏虚，肾主骨腰，失养则痛，故主肾虚精血不足。"}, {"name": "主脾虚寒湿", "desc": "两关沉细，关候脾胃，沉主里，细主气血不足、阳运无力。原文见嗳腐、腹胀、泄有声，断为中阳不振、寒湿食积内阻，久防成膈，故主脾胃虚寒、湿食交阻。"}, {"name": "主肝火犯肺", "desc": "左关弦数、右寸弦大滑，兼两尺沉细。原文见咳呛气急、发热吐涎、居经不行，断为血不养肝、木火疏泄太过、上克肺金，肺阴伤而肝火无制，故主肝火犯肺、金受火刑。"}], "n": {"主肾虚": 1, "主脾虚寒湿": 1, "主肝火犯肺": 1}, "a": {"2018": "主肝火犯肺", "15702": "主脾虚寒湿", "19957": "主肾虚"}, "t": 3, "np": 0}, "pc:关+弦+虚": {"o": "关·弦虚脉总属本虚标实、虚实夹杂之候。虚主气阴不足，为病之本；弦主肝旺、饮邪或肝郁，为病之标。其病机主要涉及肝旺乘脾、肝阴不足、水火未济及气阴两虚四类。肝旺乘脾者，弦为肝木偏亢，虚为脾土不足，木乘土位，统血失职；肝阴不足者，虚弦为肝体失养，相火不静；水火未济者，关虚弦兼尺虚数，肾水亏而心火旺，阴阳失交；气阴两虚者，虚脉主气阴亏耗，弦脉示肝旺或饮停，虚实交织。四类之间常相兼为病：肝阴不足可致相火妄动，进而水火未济；肝旺乘脾又常兼气阴两虚。总以本虚为主，标实为次，治当扶正兼以调肝、交通水火。", "c": [{"name": "主肝旺乘脾", "desc": "关脉候脾胃，弦为肝旺，虚为不足。弦虚并见，主肝木乘脾、脾虚不统。如两关弦虚，先血后粪，遇劳而发，属脾虚不能统血、肝木乘脾之候，故用黄土汤温脾摄血。"}, {"name": "主水火未济", "desc": "关虚弦兼尺虚数或濡耎，为肾水亏虚、相火妄动，水火不交。如左关虚弦、两尺虚数，肾水不能上济心火，相火循经上扰清窍而耳鸣；尺举数按不足，阴精不充，虚火内动。"}], "n": {"主肝旺乘脾": 1, "主水火未济": 2}, "a": {"8580": "主肝旺乘脾", "15454": "主水火未济", "15542": "主水火未济"}, "t": 3, "np": 0}, "c:细+坚": {"o": "细坚脉总以阴血不足为本，兼见邪实内结之象。其脉细主阴血亏虚，坚主邪气固结、脉道不柔。所主病机主要有五：一为阴血不足，脉失濡养；二为肝阳上逆，阴亏阳亢，血随气逆；三为瘀血内停，营血不足而络脉不柔，瘀血未净；四为正虚邪结，阴阳不相顺接，邪伏深入；五为湿毒蕴结，本虚标实，病根深伏。各类之间，阴血不足为共同基础，而坚象则提示邪实内结，或为阳亢，或为瘀血，或为邪伏，或为湿毒，形成虚中夹实、本虚标实之候。临床需结合兼脉及症候，辨其邪实性质与病位深浅。", "c": [{"name": "主阴血不足", "desc": "细为阴血亏虚之象，坚则脉道不柔。如‘细为阴血不足’，‘坚细为营血不足而络脉不柔’，均示阴血亏少，脉失濡养，故见细坚。"}], "n": {"主阴血不足": 2}, "a": {"1026": "主阴血不足", "8124": "主阴血不足"}, "t": 2, "np": 0}, "c:沉+长": {"o": "长沉脉总属沉取见长之复合脉，其总病机以里实、阳盛、热瘀为主，兼及肝郁。右长左沉示气分热盛而血分瘀滞，为瘀热在里；沉数长主里热壅盛；长沉涩为一阳二阴，主阳盛阴遏；沉滑长为阳多阴少；沉长弦则关乎肝郁魂越。诸类之间，或为热邪内陷血分，或为里热亢盛，或为阳气偏胜而阴受遏，或为肝木失制而魂越，皆以沉定病位在里、以长示气血涌盛或气机伸展为共同特征，而兼象不同则病机各异。", "c": [{"name": "主瘀热在里", "desc": "脉右长左沉，右长主气分热盛，左沉主血分瘀滞，合示热邪由气分内陷血分，瘀热互结于里。原文见热病经水适至，舌痿饮冷、心烦热、神气忽清忽乱，正是瘀热在里、蓄血如狂之候。"}], "n": {"主瘀热在里": 2}, "a": {"1843": "主瘀热在里", "24524": "主瘀热在里"}, "t": 2, "np": 0}, "pc:六+虚+芤": {"o": "虚芤脉总主阴血亏虚、气血不足，兼见虚火内扰之病机。芤主失血，虚主神气不足，二者相合，反映血去脉空、气血未充。失血之后，阴血亏虚，水不制火，则虚火内生，故见潮热、烦热；若阴不潜阳，肝阳偏亢，则见胁痛。其病机以阴血亏虚为本，虚火、肝旺为标，虚实夹杂。两类脉象共同提示正气已伤，阴血难复，治疗当益阴培元、降火潜阳，不可纯用寒凉或峻补。", "c": [{"name": "主失血", "desc": "芤脉中空，如按葱管，主血去脉空。原文'瘀流失血'后'六脉芤虚'，且'芤主失血'，直接点明失血致脉道空虚，故芤脉主失血。"}], "n": {"主失血": 2}, "a": {"1936": "主失血", "1937": "主失血"}, "t": 2, "np": 0}, "pc:左+数+急": {"o": "左·数急脉总起来主虚性病机，以阴液亏虚、虚阳上浮为核心。数急虽似热象，但结合左脉沉缓或迟软，实为阴分受困、阴血不足，虚阳不能潜藏而浮越。其下属数弦急脉主肝火亢盛，数小急脉主正虚邪郁，数大急脉主本虚标实，均体现数急脉在虚损基础上兼夹他邪或他脏同病。各类之间以正虚为本，虚阳上浮为标，或兼肝火、或兼邪郁、或兼多脏虚损，总属虚实夹杂、以虚为主的病理格局。", "c": [{"name": "主虚阳上浮", "desc": "左脉沉缓、右脉数急，沉缓属阴分受困，数急为虚阳上浮。原文见热炽谵语、神识昏迷、面黑目赤、上热下冷、舌干黑、肢体若僵，似水衰火炎而实为风邪所中、误治致阴阳乖违，故数急脉主虚阳浮越。"}], "n": {"主虚阳上浮": 2}, "a": {"8329": "主虚阳上浮", "8360": "主虚阳上浮"}, "t": 2, "np": 0}, "pc:右+涩+软": {"o": "右·涩软脉总起来主本虚标实之候，以正虚为本，气滞、湿滞为标。其脉象涩而软，软为虚，涩为滞，故所主病机主要包括气机郁滞、本元亏虚及湿滞内停三类。气滞多因邪阻，如伏暑晚发，气机不畅；本元亏虚则因久病或积劳伤阳，气血不足；湿滞则因脾肾阳虚，运化失职，水湿内停。三者相互关联，虚可致滞，滞可加重虚，形成虚实夹杂之态。脉象演变中，涩滞可转为软涩，再转弦数，反映邪从热化、正虚邪实之动态变化。总以虚损为基础，兼夹气滞湿阻，治疗需扶正祛邪，标本兼顾。", "c": [{"name": "主气滞", "desc": "涩脉主气机郁滞，如原文'脉形涩滞'，因伏暑晚发，邪阻气机，升降失常，故见脘闷拒按、气逆汗频等症。涩滞不利，反映气行不畅，郁而化热，为邪实阻滞之象。"}], "n": {"主气滞": 2}, "a": {"13098": "主气滞", "13931": "主气滞"}, "t": 2, "np": 0}, "pc:两+沉+微": {"o": "两·沉微脉总属阳气衰微、阴寒内盛，兼见气血不足。沉为里、为阴，微为阳衰，两尺候肾与命门、胞宫，故其病机核心在肾阳亏虚、阴寒内伏。抽样两段中，一者见形肥色淡紫、艰于育子，脉证合参为肾虚血亏、冲任失养，法当补血益气；一者以“两尺脉沉微”为用药指征，主六腑沉寒、回三阴厥逆，强调真阳衰微、沉寒内伏。下属沉微弱脉更兼弱象，直断为虚寒，总病机为阳气衰微、阴寒内盛，弱为气血不足，三象相合反映正气虚馁而寒邪内侵。三类病机相互关联：真阳衰微为根本，肾虚血亏与气虚为阳气不足在气血、冲任层面的具体表现，阴寒内盛则贯穿其中。临证需脉证合参，不可拘泥，原文“脉难尽凭”之叹亦提示脉象与病证非必完全相应。", "c": [{"name": "主肾虚血亏", "desc": "两尺脉沉微，尺部候肾与胞宫，沉为里、微为阳衰，示肾气与阴血不足，冲任失养。原文见形肥色淡紫、艰于育子，法当补血益气，故主肾虚血亏、冲任不足之病机。"}], "n": {"主肾虚血亏": 2}, "a": {"15256": "主肾虚血亏", "25605": "主肾虚血亏"}, "t": 2, "np": 0}, "pc:左+浮+小": {"o": "左·浮小脉总属虚候，以气血两虚为核心，兼见阳气外脱、脾虚失运、血虚失荣等变。浮为阳气外浮不敛，小为脉道细少，无力为正气不足，故其主病机以虚为主。段右脉浮小无力、左脉沉弱无力，疟止食进后便闭，示气血两虚、肠失濡润；段左脉浮微似有似无、右脉浮小按之不足，灸后气泄、脾阳衰败，为阳气外脱之危候。下属更具体脉中，左·沉浮小脉总主风邪在表、脾肺气滞水停与正气已伤，左浮为风邪袭表，右沉为脾肺气滞水停，脉小示正气不足；左·浮小芤脉总属虚候，以血虚为核心，兼见气亏。各类之间相互关联：气血两虚可致脾虚失运，脾虚失运又可加重气血不足；阳气外脱为气血虚极之变；血虚失荣为气血虚在血分侧重。总以虚为本，或兼外邪、水停，然脉小无力始终示正气不足。", "c": [{"name": "主气血两虚", "desc": "浮小无力，按之不足，为气血大虚之象。浮为阳气外浮不敛，小为脉道细少，无力为正气不足。如段右脉浮小无力，左脉沉弱无力，疟止食进后便闭，示气血两虚、肠失濡润；段右脉浮小按之不足，左脉浮微似有似无，为灸后气泄、脾阳衰败、气血大虚。"}], "n": {"主气血两虚": 2}, "a": {"15082": "主气血两虚", "15087": "主气血两虚"}, "t": 2, "np": 0}, "c:实+牢": {"o": "牢实脉总起来主邪实内结、坚积深痼，其病机核心为邪气壅盛、结聚不散。具体而言，牢实脉可主邪实内结，如癫狂脉实牢为邪实内结、正气尚充；可主瘀热固结，如吐血后脉牢实为瘀热固结、正不胜邪；数牢实相合则主火盛、邪结深痼与气逆上冲，反映火邪内盛、结聚深痼并致气逆；在正虚邪实的情况下，牢实脉与沉细脉对举，提示正气存否决定预后。各类病机之间相互关联：邪实内结是基础，瘀热固结为邪结的一种具体表现，火盛气逆为邪结化火、气机上逆的变证，而正虚邪实则强调邪实与正虚的对比关系。牢实脉总以邪实为要，其预后取决于正气强弱及脉证是否相符。", "c": [{"name": "主邪实内结", "desc": "牢实脉主邪气壅盛、坚积内着。原文如吐血脉牢实，牢为坚积内着、实为邪气壅盛；癫狂脉实牢，实牢为邪实内结。脉象坚劲有力，反映邪气结聚深痼，正气尚能抗邪。"}], "n": {"主邪实内结": 2}, "a": {"21145": "主邪实内结", "21171": "主邪实内结"}, "t": 2, "np": 0}, "pc:尺+数+濡": {"o": "尺·数濡脉总起来主湿温阴伤、痰热气弱、下虚阳浮及外感风燥之证。其脉象由三部合参：濡主湿，数主热，尺软主下虚。本案冬温之候，外感袭于肺胃，故见数脉与身热咳呛；湿痰内蕴，气机上逆，故脉濡而痰鸣气升；下元虚衰，不能潜藏，故尺脉软而阳失潜藏。四类病机相互关联：下虚为根本，外感为诱因，湿温痰热为标象，阴伤气弱为转归。总属本虚标实、寒热错杂之候，以湿温阴伤为主线，兼见痰热、下虚及外感，临证需权衡虚实主次。", "c": [{"name": "主湿温阴伤", "desc": "脉濡主湿，数主热，尺部濡数反映湿温之邪蕴蒸，且阴液受损。原文'濡数主湿温阴伤'直接点明，湿温内蕴，热灼阴伤，故见尺脉濡数。"}], "n": {"主湿温阴伤": 1}, "a": {"63": "主湿温阴伤"}, "t": 1, "np": 0}, "pc:右+大+弱": {"o": "右大弱脉（右大左弱）总属阴阳乖违、上下不交之候。其右脉大主上部火升，左脉弱主下焦虚冷，二者并见，反映阳浮于上、阴寒于下，阴阳失于交通。所主病机可归为三类：一为火升于上，二为虚冷于下，三为阴阳乖违。三者实为一体：下焦虚冷，阴不敛阳，则虚阳上浮而为火升；火升于上，更耗阴液，下元愈虚，形成恶性循环，终致阴阳乖违。故治疗不可单纯补血涩剂，当以通阳摄阴、交通上下为法，使阳降阴升，孕育可望。", "c": [{"name": "主火升", "desc": "右脉大，为阳气上亢、火热上炎之象。原文谓“右大主上部火升”，症见嘈杂、经水紫黑，皆火扰于上之征。火性炎上，故右脉应之而大，非实火即虚阳上浮。"}], "n": {"主火升": 1}, "a": {"1722": "主火升"}, "t": 1, "np": 0}, "pc:关+沉+小": {"o": "关·沉小脉总起来主气血两虚，兼有瘀滞。沉为脉道不充，小为气血不足，故脉见沉小，多提示气血两虚。原文以左关尺虚濡、右寸虚软，关脉沉小，断为气血两虚，经行愆期、痛甚经行、血中兼块，治以益气养营为主，佐调血通经。可见沉小脉所主病机以虚为本，因虚致瘀，虚中夹实。其下属更具体脉关·沉小实脉则主里有形实邪内结，以积、寒凝、症瘕为核心病机，与单纯沉小脉之虚证不同，提示沉小脉需结合兼脉（如实、弦紧等）辨别虚实。", "c": [{"name": "主气血两虚", "desc": "关脉沉小，沉为脉道不充，小为气血不足，故主气血两虚。原文见左关尺虚濡、右寸虚软，关脉沉小，断为气血两虚，经行愆期、痛甚经行、血中兼块，治以益气养营为主，佐调血通经。"}], "n": {"主气血两虚": 1}, "a": {"15876": "主气血两虚"}, "t": 1, "np": 0}, "pc:右+弦+空": {"o": "右·弦空脉总属虚实夹杂、肝脾不调之候。右脉候脾胃，空为正气不足，主脾胃气弱；弦为肝木偏旺，主气机郁滞。二者并见，反映肝旺乘土、脾虚不运，且常伴余邪未清，形成正虚邪恋之势。原文身凉额不热、舌苔腻白、烦渴渐减、正渐弱，正是暑湿未楚而正气渐伤之象。故本脉所主，以脾虚为本，肝旺为标，正虚邪恋为枢机，三者相互关联：脾虚则脉道不充而空，肝旺则脉气紧张而弦，正虚则无力抗邪而余邪留恋。临证需扶正化湿，未雨绸缪，防虚态毕集。", "c": [{"name": "主脾虚", "desc": "右脉候脾胃，空为不足之象。原文右空直接提示脾胃气弱，结合身凉、烦渴渐减、正渐弱，说明中焦气虚，运化无力，故脉道不充而空。"}], "n": {"主脾虚": 1}, "a": {"18045": "主脾虚"}, "t": 1, "np": 0}, "pc:关+大+弱": {"o": "关·大弱脉总属虚证，主气血不足、大虚之候。其脉大而弱，大则为虚，弱为气血不足；兼尺脉涩小，涩主血少，小主气虚。寸关候上中焦，尺候下焦，上下皆见虚象，故整体反映气血大虚。具体而言，关脉大弱侧重脾胃虚衰，运化无力；尺脉涩小侧重下焦精血亏耗。三者相互关联，脾胃虚衰可导致气血生化不足，下焦精血亏耗又加重全身虚损，共同构成气血大虚的病理基础。", "c": [{"name": "主气血大虚", "desc": "脉大而弱，大则为虚，弱为气血不足；两尺涩小，涩主血少，小主气虚。寸关候上中焦，尺候下焦，上下皆见虚象，故断为气血不足、大虚之证。"}], "n": {"主气血大虚": 1}, "a": {"18340": "主气血大虚"}, "t": 1, "np": 0}, "pc:六+紧+伏": {"o": "紧伏脉总起来主邪毒深伏、气机壅塞之实证。其紧象主痧毒郁闭、气机壅塞，伏象主邪深脉道不利、痰浊内闭，不匀则示气血运行失序。三者相互关联：痧毒郁闭可致气机壅塞，痰浊与痧毒互结则深伏脉道，闭阻心窍经络，发为痫证。原文以放痧去毒、滚痰丸逐痰降气而愈，印证紧伏脉所主为邪实内闭、气血不畅之病机，治当祛邪通闭、逐痰降气。", "c": [{"name": "主痧毒郁闭", "desc": "紧脉主痧毒郁闭、气机壅塞，原文载'六脉紧伏不匀'，紧为痧毒内闭之象，毒血瘀滞经络，故见手臂少阳穴痧筋，放痧后毒去气通，脉象得缓。"}], "n": {"主痧毒郁闭": 1}, "a": {"18469": "主痧毒郁闭"}, "t": 1, "np": 0}, "c:浮+牢": {"o": "浮牢脉总起来主邪实内结、气机壅闭之实证。其脉浮而牢，浮示邪气偏表或浮越，牢示坚结内着，合而主积邪内结、寒实坚结及气机壅闭三类病机。原文论积聚脉象，浮而牢为积病脉之一，贲豚由寒邪留结、脏气传变而成；又论关格由阴阳气不和、营卫不通，阴阳俱盛不得相营，致气痞结腹内胀满、二便俱不通。三类病机相互关联：寒实邪结为因，气机壅闭为果，积与关格为典型表现。浮牢脉总以实证为纲，不主虚证，其病位可在表里之间，病性属寒实坚结，气机不通。", "c": [{"name": "主积邪内结", "desc": "浮牢脉主积邪内结。原文列积聚脉象，浮而牢为其中之一，贲豚等积病由寒邪留结、脏气传变所致。浮主邪在表，牢主坚结，合示邪气结聚成形，留着不移，故主积。"}], "n": {"主积邪内结": 1}, "a": {"22062": "主积邪内结"}, "t": 1, "np": 0}, "pc:右+涩+伏": {"o": "右·涩伏脉总属虚候，以五脏虚损为核心病机。其脉举指或滑，按之则沉小微弱短涩，反映虚阳浮于外而根本不足，故主脏虚、阳虚外浮及气衰三类。脏虚为总纲，涵盖肺脾肾等右部所候之脏；阳虚外浮为虚阳不敛之变；气衰则由脏虚所致，见肠鸣、足冷、食不入、语声破散等症。三者相互关联，皆以正气内衰为本，涩伏之象为凭，临床当结合右部脏腑分候，细辨虚损所在。", "c": [{"name": "主脏虚", "desc": "原文引华元化论脏虚，诊脉“举指而滑，按之而微”，又言“按之沉小微弱短涩软濡，俱为脏虚”。涩伏之脉，按之沉小短涩，正是正气内衰、根本不足之象，故主五脏之虚，尤以右部候肺脾肾，虚象更著。"}], "n": {"主脏虚": 1}, "a": {"22693": "主脏虚"}, "t": 1, "np": 0}, "s:解索": {"o": "解索脉总属无胃气之真脏脉，其象散乱无绪、按之无根，主脏气衰败、元气涣散，为危重死候。所主病机以正气虚脱为本：或真脏气绝，或元气涣散，或胃气衰败，皆脉失冲和、根本将竭之象。其兼见数而无力者，为虚阳外浮；兼见滑数洪滑等，则为正虚邪实、痰食湿热壅闭。诸类之间，总以虚败为枢：纯虚者属气绝、元脱、胃败；虚中夹实者属正虚邪实、虚阳浮越。故解索脉虽可见于多种病机，然其核心皆不离胃气将绝、真元涣散，预后多凶。", "c": [{"name": "主真脏气绝", "desc": "解索脉散乱无绪、无胃气，是脏腑真气败绝之象。原文多列于死脉，如“搭指散乱如解索”“脉动数而随散乱无次绪”，并明言“真藏脉见”“胃气已无”，故主肾、命门等脏气将绝，预后凶险。"}, {"name": "主元气涣散", "desc": "解索脉散乱无根，主元气脱散、神气将绝。如产后大泻、吐泻交作后脉“散乱如解索状”，伴神气惫、恍惚、循衣摸床，是元气败绝之死候；又“左三部散乱无绪，如解索状”为正气涣散、根本已竭。"}, {"name": "主胃气衰败", "desc": "解索脉无从容和缓之胃气，主胃气衰败。原文谓“搭指散乱如解索”为无胃气之脉，又“气口又兼解索”乃胃气将败之危兆；胃气一败，则脉失冲和，故主病重。"}, {"name": "主虚阳外浮", "desc": "解索脉可兼数而无力，主虚热浮越、元气不敛。如产后误下，六脉皆数，后“散乱无伦，脉又数”，为虚阳外浮之象，非实热；以温补得效，数脉渐退，说明解索兼数主虚阳外浮。"}, {"name": "主正虚邪实", "desc": "解索脉见于久病正虚而痰食湿热壅盛者，主正虚邪实、气机壅闭。如“左三部散乱如解索”而右脉洪滑弹指，为久病脏衰、痰食内阻；又脉滑数兼解索，为湿热误补、充斥三焦，邪正混淆，病势危重。"}], "n": {"主真脏气绝": 9, "主元气涣散": 2, "主胃气衰败": 2, "主虚阳外浮": 3, "主正虚邪实": 2}, "a": {"4089": "主虚阳外浮", "5987": "主元气涣散", "5988": "主虚阳外浮", "6226": "主真脏气绝", "6281": "主元气涣散", "6282": "主虚阳外浮", "6521": "主正虚邪实", "13040": "主胃气衰败", "13808": "主胃气衰败", "14004": "主正虚邪实", "17433": "主真脏气绝", "19376": "主真脏气绝", "21186": "主真脏气绝", "21823": "主真脏气绝", "22821": "主真脏气绝", "22824": "主真脏气绝", "26549": "主真脏气绝", "26659": "主真脏气绝"}, "t": 18, "np": 0}, "pe:关+缓": {"o": "关·缓脉总属脾胃病变，以虚、湿、风、实为四大纲。缓为胃气之象，关候脾胃，故其主病多不离中焦。虚者，脾胃气虚、气血两亏、中阳不振，脉缓而弱、微、迟；湿者，寒湿、湿热、湿痰内蕴，脉缓而濡、沉、滑；风者，风邪外袭、内犯中焦，脉浮缓或大缓；实者，痰食火邪内结、积滞血瘀，脉缓而滑大、沉实或涩。此外，弦缓主木乘土，乃肝脾同病。诸类之间，虚为本，湿、风、实为标，常相兼为患，如虚中夹湿、风邪引动肝木等，形成本虚标实、寒热错杂之候。总以脾胃为中心，辨其虚实寒热、兼夹邪气，方为全面。", "c": [{"name": "主虚损", "desc": "关·缓脉主脾胃气虚、气血两亏。缓为胃气孱弱之象，关候脾胃，故见纳运无力、肌肉削、不能食。如关·弱缓脉示脾阳式微，关·微缓脉示气血两亏，关·缓迟脉示中阳不振，皆以正虚为本。"}], "n": {"主虚损": 2}, "a": {"6248": "主虚损", "6541": "主虚损"}, "t": 2, "np": 0}, "ps:两寸+浮": {"o": "两寸浮脉总属上焦病变，以阳浮气逆为基本特征。寸候上焦，浮为阳脉，故凡气火上升、表邪外袭、痰浊壅塞、上盛下虚及虚损内伤，皆可见两寸浮。其类虽分五端，然核心病机在于“上焦气机不降、阳浮于上”：气火与痰浊为实邪上壅，表邪为外束，上盛下虚与虚损内伤则为本虚标实、阴阳不相维系。实者脉多浮大、浮滑、浮紧、浮洪，虚者脉多浮空、浮而无力。临证须合关尺及兼脉辨之：浮紧主寒表，浮滑主痰湿，浮洪主火盛，浮空主虚损，尺弱或如无则下元亏虚。总以脉症合参，分清虚实寒热，不可见浮即作表论。", "c": [{"name": "主气火上逆", "desc": "两寸浮大或浮洪，寸候上焦，浮大为阳亢气火上升之象。原文见“气火上升，头眩，甚则欲呕吐”，或“浮洪而溢”主君相二火独盛、喉痹，皆因肝阳化火、君相火亢，上冲清窍，故脉浮大而盛。"}, {"name": "主表邪外袭", "desc": "浮主表，寸候上焦。原文“两寸脉浮紧”为风寒袭表、清阳被束；“两寸关浮滑”为风湿外乘、身热恶寒。浮紧主寒邪，浮滑主风湿兼痰，皆属外邪在表、卫阳被遏之象。"}, {"name": "主上盛下虚", "desc": "两寸浮滑或浮大，两尺弱或如无，寸浮主上焦气逆痰壅，尺弱主下元虚衰。原文“上盛下虚症”见头痛、脐腹疼需温熨；“两寸浮，两尺如无”为呕恶不止、气逆于上而中下焦虚竭，皆上实下虚、阴阳不相维系之候。"}, {"name": "主虚损内伤", "desc": "浮而空或浮大无力，非表邪。原文“两寸脉浮而空、关尺微细”，因努挣伤气、阴乘阳位，便后寒热，乃内伤虚损、阴阳不相顺接；又“两寸浮大”见于郁怒产后，虽似外感而实为肝郁乘脾、气机升降失司，属内伤范畴。"}], "n": {"主气火上逆": 4, "主表邪外袭": 2, "主上盛下虚": 2, "主虚损内伤": 1}, "a": {"807": "主气火上逆", "3450": "主虚损内伤", "6073": "主上盛下虚", "6367": "主上盛下虚", "12252": "主表邪外袭", "16658": "主气火上逆", "17065": "主表邪外袭", "18380": "主气火上逆", "18606": "主气火上逆"}, "t": 9, "np": 0}, "ps:左尺+细": {"o": "左尺细脉总属肾阴精血不足、脉道不充之象，其核心病机为肾虚，但兼象不同则所主有别。细而数者，主阴虚火旺，虚火内扰，可见不寐、劳瘵、肌热等；细弱无力者，主肾气亏虚、阴精不足，不能涵阳固摄；细而坚硬鼓指者，主肾经湿毒蕴结，久郁化热，结聚不散，属虚实夹杂；细数而虚弱并见右尺迟软者，主足三阴亏损、虚热无火之劳瘵。四类之间，阴虚火旺与肾虚不固同属正虚，前者偏火旺，后者偏气衰；湿毒蕴结为虚中夹实；虚热劳瘵则阴虚与元气不摄并见。总以肾阴亏虚为本，或兼火、兼虚、兼毒、兼劳，须结合兼脉及症候分判。", "c": [{"name": "主阴虚火旺", "desc": "左尺细数或细弱无力，为肾阴亏虚、阴不制阳之象。原文言“细数主阴亏火旺”，言“阴虚不寐”，言“左肾真阴不足，阴虚不能制火故细数”，言“肾阴亏而虚火妄动”，皆以细脉示阴血不足，数或弱示虚火内扰。"}, {"name": "主肾虚不固", "desc": "左尺细弱无力，为肾气亏虚、阴精不足，脉道不充。原文“左尺脉细弱无力”合“阴虚不寐”，重申“阴精不足、脉道不充”，“左尺脉虚弱而细数”为真阴不足，“左尺虚弱”示元气不摄。细弱无力主肾虚，不能固摄与涵养。"}, {"name": "主湿毒蕴结", "desc": "左尺细而坚硬鼓指，为肾经湿毒深伏、久郁化热、结聚不散之象。原文“脉细为阴血不足，左尺坚硬鼓指乃湿毒深伏于肾、久郁化热、结聚不散”，并见喉间糜碎、舌下肿胀，示病根深伏，非单纯虚证。细为阴伤，坚硬鼓指为毒结。"}, {"name": "主虚热劳瘵", "desc": "左尺虚弱或细数，右尺迟软，为足三阴亏损、虚热无火、元气不摄之象。原文言劳瘵“属足三阴亏损，虚热无火”，脉见“左尺虚弱或细数、右尺迟软”，示肾阴亏而虚火妄动，火土太旺金水衰涸，血随火泛而衄吐血。"}], "n": {"主阴虚火旺": 3, "主肾虚不固": 1, "主湿毒蕴结": 1, "主虚热劳瘵": 1}, "a": {"62": "主阴虚火旺", "8048": "主湿毒蕴结", "12296": "主阴虚火旺", "12297": "主阴虚火旺", "18312": "主肾虚不固", "23196": "主虚热劳瘵"}, "t": 6, "np": 0}, "ps:左尺+浮": {"o": "左尺浮脉总属肾与阴分病变，以虚为本、以火为标。其主病机可归为四类：阴虚火旺、湿热郁蒸、肾虚水亏、内伤衄血。四者皆根于肾阴不足或阴分受伤，致使虚火浮动或湿热郁蒸于外。阴虚火旺与肾虚水亏侧重虚火，湿热郁蒸兼夹实邪，内伤衄血则由虚火迫血而致。诸类之间相互关联，虚火可致衄血，湿热可伤阴分，总以肾阴亏虚、虚火浮动为核心病机。", "c": [{"name": "主阴虚火旺", "desc": "左尺候肾与阴分，脉浮为阴亏不能潜藏，虚火上炎。原文如「左尺脉浮，肝肾阴虚」「左尺浮洪，肾不足、肾家有火」，均示肾阴不足、虚火浮动，故主阴虚火旺之病机。"}, {"name": "主湿热郁蒸", "desc": "浮脉主邪郁于外，按之弦数示热郁于内。原文「湿郁为热，变作沙淋」「左尺脉浮，按之弦数」，湿热煎熬阴液成沙，病经半载阴分已伤，故主湿热郁蒸兼阴伤之病机。"}, {"name": "主肾虚水亏", "desc": "左尺浮洪无力为水亏火旺，肾水不足则虚阳外浮。原文「左尺浮洪无力为水亏火旺」「左尺浮洪，肾不足」，均示肾水亏虚、虚阳上浮，故主肾虚水亏之病机。"}, {"name": "主内伤衄血", "desc": "左尺脉浮主肝肾阴虚，虚火上炎，火迫血溢。原文「左尺脉浮，肝肾阴虚」「诸脉皆主内伤衄血之病机」，并治以犀角地黄汤、凉八味丸滋阴降火，故主内伤衄血之病机。"}], "n": {"主阴虚火旺": 1, "主湿热郁蒸": 1, "主肾虚水亏": 1, "主内伤衄血": 2}, "a": {"9041": "主湿热郁蒸", "18419": "主肾虚水亏", "24738": "主内伤衄血", "24739": "主内伤衄血", "27681": "主阴虚火旺"}, "t": 5, "np": 0}, "ps:左寸+动": {"o": "左寸动脉总起来主气机躁动、血行不畅之病机，具体可归纳为三类：一主燥屎内结、腑气不通，动为气机被阻而躁动，沉涩应指如有物为燥屎内结之征；二主妊娠胎动，胎气初结、血聚养胎，左寸候心，故见动滑摇摆；三主血虚气阻，女子经带胎产诸病多本于血虚气弱，气阻血行不畅亦可见动脉。三类之间，燥屎内结属邪实阻滞，妊娠胎动属生理性气血壅聚，血虚气阻属虚实夹杂，均以气机躁动、血行不畅为共同病理基础，而左寸候心，心主血脉，故动脉见于左寸多与心血运行及胎气内动相关。", "c": [{"name": "主燥屎内结", "desc": "左寸动脉可因燥屎内结、腑气不通而出现。原文见左寸发动，关尺沉，右寸关沉涩如有物应指，尺沉数，断为燥屎内结。动为气机被阻而躁动，沉涩应指如有物为燥屎内结之征，郁热内蕴故数。"}, {"name": "主妊娠胎动", "desc": "左寸动脉主妊娠胎气初结、血聚养胎。原文载怀孕月余，左寸脉动滑，有摇摆之状，为妊娠之脉。左寸候心，胎气内动、血聚养胎，故见动滑摇摆，并伴内热呕吐等妊娠恶阻之象。"}], "n": {"主燥屎内结": 1, "主妊娠胎动": 2}, "a": {"3061": "主燥屎内结", "16528": "主妊娠胎动", "16532": "主妊娠胎动"}, "t": 3, "np": 0}, "ps:两寸+细": {"o": "两寸细脉总属正虚，以心肺气阴不足为核心。细为虚象，寸候上焦，故心肺气虚、阴血不足多见。其类有四：一为一般正虚，心肺气阴耗损；二为心脾两虚，劳心伤脾，气血不足；三为心肾不交，寸细尺濡，心神不宁；四为死候，寸细而关尺无神，正气败绝。四类皆以虚为本，轻者心肺气阴不足，重者累及脾肾，甚则脏气败绝而预后不良。临证当结合兼脉及症状，辨其虚损脏腑与程度。", "c": [{"name": "主心脾两虚", "desc": "两寸细小兼关脉虚耎，为心脾两伤。段因劳心会计、预事心烦，致胃中郁郁、呕哕咳呛，脉细小虚耎，示气血不足、心脾亏虚，故先调心脾。"}, {"name": "主心肾不交", "desc": "两寸细耎难寻，左尺虚濡，为心肺气阴不足、肾虚不纳。段夜寐不安、心神不宁，乃心肾不交、荣卫不和，故法宜荣卫并治，佐以养神安魂。"}, {"name": "主死候", "desc": "两寸脉细而关尺无神，为正气败绝之死候。段真头疼而两寸俱细、关尺无神，原文断为“脑已坏矣”，越日而亡，死后十指皆青，脉无神与死候相应。"}], "n": {"主心脾两虚": 1, "主心肾不交": 1, "主死候": 1}, "a": {"12251": "主死候", "15650": "主心肾不交", "15748": "主心脾两虚"}, "t": 3, "np": 0}, "u:无根": {"o": "无根脉总属正气虚衰、根本动摇之象，其核心病机为阳气衰绝、阴血脱竭、虚火上浮、气散不敛、寒闭脉道及阴亏液涸。诸类或为阳气暴脱，或为阴血枯竭，或为虚阳浮越，或为气散不收，或为寒邪闭阻，或为阴液亏耗，皆致脉道不充或不通，故按之无根。其中阳气衰绝与寒闭脉道多急危，阴血脱竭与气散不敛亦属重候，虚火上浮与阴亏液涸则偏于虚损。各类之间常相互转化，如寒闭日久可致阳脱，血脱可致气散，阴亏可致火浮，总以本虚为主，或兼寒闭，治当温阳、补血、纳气、养阴、散寒，随证施治。", "c": [{"name": "主阳气衰绝", "desc": "脉无根而见六脉全无、按至附骨无有，伴四肢逆冷、吐泻腹痛、僵卧如死，为阴寒极盛、阳气败绝之候。如段5630、5634、12123所示，寒邪直中或痼冷内结，阳气不能外达，脉道不通，故脉伏不出，主危候。"}, {"name": "主阴血脱竭", "desc": "脉似有若无、重按全无，见于大失血或热病后期，如段12027血冒昏不知人、段5205热退舌干，皆阴血枯竭、脉道不充之象。血脱则气亦脱，阴伤则脉无根，故脉来无根而主阴血亏耗。"}, {"name": "主虚火上浮", "desc": "脉来少力而喘咳，断为火无根，如段4804。虚火不归元，浮越于上，下元空虚，故脉少力无根。此非实火，不可清降，须补纳引火归元，主肾虚火浮之病机。"}, {"name": "主气散不敛", "desc": "脉虚大无根、浮缓散慢，甚则神离反疾，如段24878气散腹胀之脉。正气涣散，根本已亏，气不敛摄，脉道松弛，故脉无根而散漫，主气散欲脱之危候。"}, {"name": "主寒闭脉道", "desc": "六脉皆无而身寒战、头疼喘促，如段20590。风寒深入，经络阻塞，阳气被遏不能外达，脉道不通，故脉闭不见。此属伤寒表闭或寒邪直中，主寒凝脉闭之病机。"}, {"name": "主阴亏液涸", "desc": "高年脉按之如无，舌绛无津，如段13200。阴液亏虚，脉道不充，故脉无根。阴虚肠燥，可转滞下，脉虚证实，主阴液难充、虚多实少之候。"}], "n": {"主阳气衰绝": 2, "主阴血脱竭": 2, "主虚火上浮": 1, "主气散不敛": 1, "主寒闭脉道": 3, "主阴亏液涸": 3}, "a": {"1839": "主阴血脱竭", "1855": "主阳气衰绝", "4804": "主虚火上浮", "5205": "主阴亏液涸", "5630": "主寒闭脉道", "5634": "主寒闭脉道", "12027": "主阴血脱竭", "12123": "主阳气衰绝", "12577": "主阴亏液涸", "13200": "主阴亏液涸", "20590": "主寒闭脉道", "24878": "主气散不敛"}, "t": 12, "np": 0}, "rc:沉取+数+弦": {"o": "沉取数弦脉总属邪热内郁、肝胆火旺，兼见阴分亏虚之候。弦主肝胆气滞或木火，数主邪热，沉取则病位偏里。其病机主要有五：湿热郁蒸肝胆、实火内郁、虚阳浮越、邪炽阴伤、上盛下虚。各段所主虽偏重不同，但核心为热与虚并存：或湿热交蒸，或实火亢盛，或热盛劫阴而虚阳上浮，或下元亏虚而肝阳偏亢。脉证合参，弦数之脉既主邪热内郁，又因重按少力、虚软而示阴伤根本不足，故临床须辨热之虚实与阴之盈亏。", "c": [{"name": "主湿热", "desc": "脉弦数而重按隐隐，弦主肝胆，数主热，为湿热郁蒸肝胆之象。原文见黄疸，皮肤目睛皆黄、小溲赤、午后发热，脉证合参，主湿热黄疸。"}, {"name": "主实火", "desc": "弦主肝胆，数主火，重取左豁大于右，示火郁于胆经。原文谓小肠火乘胆木，为实邪，痛从背胛小肠经起，延及胸胁胆经，主实火内郁。"}, {"name": "主虚阳浮越", "desc": "脉弦数而重按少神或虚软无力，弦数为热，少神示阴虚阳越、根本不足。原文见年高疟发、颧赤鼻冷、苔黄口渴痰多，证属伏暑挟痰而阴虚阳越，主虚阳浮越。"}, {"name": "主邪炽阴伤", "desc": "脉弦而有力，数近六至，重按不甚实，示邪热炽盛而真阴亏损。原文见温病神昏谵语，单用白虎汤清邪热未滋真阴则谵语益甚，改白虎加人参汤而愈，主邪炽阴伤。"}, {"name": "主上盛下虚", "desc": "脉弦数较减轻而重按虚软无力，示肝火渐平而肾亏未复。原文见耳响作堵、腰痛连背、足跟痛，证属上盛下虚、肾亏肝旺，主上盛下虚。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主湿热": 1, "主实火": 1, "主虚阳浮越": 4, "主邪炽阴伤": 1, "主上盛下虚": 1, "其他": 0}, "a": {"3913": "主湿热", "3928": "主实火", "9130": "主上盛下虚", "13151": "主虚阳浮越", "14190": "主虚阳浮越", "14486": "主虚阳浮越", "20151": "主邪炽阴伤", "20253": "主虚阳浮越"}, "t": 8, "np": 0}, "pc2:右寸+弦+浮": {"o": "右寸浮弦脉总起来主痰饮内停，兼有肺脾两虚。其核心病机为肺气虚不能通调水道，聚液为痰、积湿为饮，痰饮阻肺则咳喘有音；而痰饮生成之源又在脾虚不能散精归肺。故本脉所主以痰饮为标，以肺脾两虚为本，属本虚标实之候。三类病机相互关联：肺虚是痰饮停聚的直接原因，脾虚是生痰之源，痰饮既是病理产物又是致病因素。原文以“弦者痰饮也”点明主病，又强调补肺健脾以绝生痰之源，正合标本兼治之意。", "c": [{"name": "主痰饮", "desc": "右寸浮弦，弦为痰饮之象。原文直言“弦者痰饮也”，并释肺气虚不能通调水道，聚液为痰、积湿为饮，痰饮停肺则咳喘有音。浮弦见于右寸，正主肺中痰饮内停。"}, {"name": "主肺虚", "desc": "浮脉主肺气不降，右寸候肺，浮弦而见右寸，提示肺气虚。原文谓肺气虚不能通调水道，下输膀胱，以致水液停聚为痰饮；又言补肺健脾以绝生痰之源，说明本脉兼有肺虚之机。"}, {"name": "主脾虚生痰", "desc": "原文强调饮食入胃，脾气散精，上归于肺；肺虚则不能通调水道，聚液为痰。右寸浮弦虽候肺，然痰饮生成之源在脾，故补肺健脾以绝生痰之源。脉象反映肺脾两虚、痰湿内生之病机。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主痰饮": 2, "主肺虚": 1, "主脾虚生痰": 0, "其他": 0}, "a": {"5842": "主痰饮", "10687": "主痰饮", "18419": "主肺虚"}, "t": 3, "np": 0}, "pc2:右关+微+缓": {"o": "右关微缓脉总属本虚标实之候。微缓主气血两亏，为正虚之根；右关滑动主痰积、湿热壅滞中焦，为邪实之标；兼左关弦搏，肝气入络，形成痰积、湿热、肝气交阻而元气已弱之局。故其病机以虚为本，以痰、湿、热、气郁为标，攻补两难，治当择性味不猛者通化。", "c": [{"name": "主气血两亏", "desc": "原文尺寸脉俱微缓，泄痢一载，明言气血两亏。微缓为正气虚衰之象，缓主正虚，微为阳衰，久痢耗伤气血，故脉见微缓，提示本虚。"}, {"name": "主痰积中焦", "desc": "右关滑动，舌苔黄白而腻，是痰积在中焦。滑主痰，动主痛，右关候脾胃，痰湿积滞中焦，故脉滑动，兼苔腻，为痰积之征。"}, {"name": "主湿热内蕴", "desc": "原文述病根为痰积、湿热、肝气，舌苔黄白而腻，湿热交阻中焦。右关滑动不仅主痰，亦主湿热，湿热郁蒸，脉道壅滞，故见滑动。"}, {"name": "主肝气入络", "desc": "左关弦搏，肝木气旺，左肋斜至脐下有梗一条，按之觉硬，乃肝气入络所结。弦主肝旺，气机郁滞，入络则成梗硬，虽非右关直接所主，但为兼见病机。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主气血两亏": 3, "主痰积中焦": 0, "主湿热内蕴": 0, "主肝气入络": 0, "其他": 0}, "a": {"10858": "主气血两亏", "13666": "主气血两亏", "14781": "主气血两亏"}, "t": 3, "np": 0}});